document.body.append(realmHuntPanel);

function renderRealmHuntRewardTier(): void {
  const preview = realmHuntPanel.querySelector(".realm-hunt-tier-preview")!;
  preview.textContent = realmHuntDifficulty === "ascendant"
    ? "ASCENDANT GUARANTEE · path weapon + rare set armour + awakened Forgemark · 2× materials"
    : realmHuntDifficulty === "veteran"
      ? "VETERAN CACHE · path weapon + 1.5× materials · first set armour guaranteed, then 35%"
      : "NORMAL GUARANTEE · path weapon + foundational materials";
}

function renderRealmHuntBoard(update: RealmHuntBoardUpdate): void {
  latestRealmHuntBoard = update;
  realmHuntPanel.querySelector(".realm-hunt-message")!.textContent = update.message;
  const contractCard = realmHuntPanel.querySelector<HTMLElement>(".realm-contract-card")!;
  contractCard.hidden = !update.contract;
  if (update.contract) {
    const contract = update.contract;
    if (!contract.completed) {
      realmHuntDifficulty = contract.difficulty;
      realmHuntPath = contract.forgeName;
    }
    contractCard.dataset.state = contract.failed ? "failed" : contract.completed ? "complete" : contract.championActive ? "champion" : "active";
    contractCard.querySelector("strong")!.textContent = contract.failed ? `${contract.pathName.toUpperCase()} FAILED`
      : contract.completed ? `${contract.pathName.toUpperCase()} COMPLETE`
      : contract.championActive ? `FINAL HUNT · ${contract.championName}` : contract.pathName;
    const lives = contract.difficulty === "ascendant" ? ` · ${contract.livesRemaining} LIVES` : "";
    contractCard.querySelector("span")!.textContent = contract.failed ? "Ascendant lives spent · begin a new contract"
      : contract.completed ? "Champion cache secured · mastery and best time recorded"
      : contract.championActive ? "The Path Champion is active in the final territory"
        : `Next: ${contract.targetName} · ${contract.modifier.toUpperCase()} · REMATCH ${contract.tier}`;
    contractCard.querySelector("b")!.textContent = contract.failed ? "FAILED"
      : contract.completed ? "COMPLETE"
        : `${contract.difficulty.toUpperCase()}${lives} · ${formatDungeonTime(contract.elapsedMs)}`;
  }
  realmHuntPanel.querySelectorAll<HTMLButtonElement>("[data-hunt-difficulty]").forEach(button => {
    button.classList.toggle("active", button.dataset.huntDifficulty === realmHuntDifficulty);
  });
  renderRealmHuntRewardTier();
  const masteryPanel = realmHuntPanel.querySelector(".realm-hunt-mastery")!;
  masteryPanel.replaceChildren();
  for (const pathId of ["fang", "venom", "crusher"] as const) {
    const mastery = update.mastery[pathId];
    const bestDifficulty: RealmHuntDifficulty | null = mastery.bestTimesMs.ascendant ? "ascendant"
      : mastery.bestTimesMs.veteran ? "veteran" : mastery.bestTimesMs.normal ? "normal" : null;
    const record = document.createElement("span");
    record.innerHTML = `<b>${pathId.toUpperCase()} · R${mastery.rank}</b><small>${bestDifficulty ? `${bestDifficulty.toUpperCase()} BEST ${formatDungeonTime(mastery.bestTimesMs[bestDifficulty] ?? 0)}` : "NO CLEAR YET"}</small>`;
    masteryPanel.append(record);
    const button = realmHuntPanel.querySelector<HTMLButtonElement>(`[data-contract="${pathId}"]`);
    if (button) button.textContent = `${pathId.toUpperCase()} · R${mastery.rank}`;
  }
  realmHuntPanel.querySelectorAll<HTMLButtonElement>("[data-path]").forEach(button => {
    const active = button.dataset.contract ? update.contract?.pathId === button.dataset.contract && !update.contract.completed
      : realmHuntPath === "all";
    button.classList.toggle("active", active);
  });
  const list = realmHuntPanel.querySelector(".realm-hunt-list")!;
  list.replaceChildren();
  const visibleHunts = update.hunts.filter(hunt => realmHuntPath === "all" || hunt.forgeName === realmHuntPath);
  for (const hunt of visibleHunts) {
    const row = document.createElement("article");
    const selected = update.selectedMobId === hunt.mobId;
    row.className = `realm-hunt-row ${selected ? "selected" : ""}`;
    row.dataset.status = hunt.status;
    const heading = document.createElement("div");
    heading.className = "realm-hunt-heading";
    const title = document.createElement("strong"); title.textContent = hunt.name;
    const territory = document.createElement("span"); territory.textContent = hunt.territory;
    heading.append(title, territory);
    const status = document.createElement("b");
    status.className = "realm-hunt-status";
    status.textContent = hunt.status === "recovering" ? `RECOVERING · ${hunt.respawnSeconds}s`
      : hunt.status === "empowered" ? `${hunt.modifier.toUpperCase()} · REMATCH ${hunt.rematchTier}` : "ALIVE · FIRST HUNT";
    const progress = document.createElement("div"); progress.className = "realm-hunt-progress";
    const relic = document.createElement("span"); relic.textContent = hunt.awakened ? `${hunt.relicName} · AWAKENED` : `${hunt.relicCount} / 3 · ${hunt.relicName}`;
    const path = document.createElement("em"); path.textContent = hunt.forgeName.toUpperCase();
    progress.append(relic, path);
    const track = document.createElement("button"); track.type = "button";
    const contractLocked = Boolean(update.contract && !update.contract.completed);
    track.disabled = contractLocked;
    track.textContent = contractLocked ? selected ? "CONTRACT TARGET" : "CONTRACT LOCKED" : selected ? "TRACKING ✓" : "TRACK HUNT";
    track.addEventListener("click", () => room?.send("realm-hunt:board", { action: "select", mobId: hunt.mobId }));
    row.append(heading, status, progress, track);
    list.append(row);
  }
}

function openRealmHuntBoard(): void {
  expeditionPanel.hidden = true;
  realmHuntPanel.hidden = false;
  resetMovementControls();
  room?.send("realm-hunt:board", { action: "sync" });
}
expeditionPanel.querySelector(".realm-hunts-open")!.addEventListener("click", openRealmHuntBoard);
realmHuntPanel.querySelector(".realm-hunt-close")!.addEventListener("click", () => { realmHuntPanel.hidden = true; });
realmHuntPanel.querySelector(".realm-hunt-back")!.addEventListener("click", () => {
  realmHuntPanel.hidden = true; openDungeonBoard();
});
realmHuntPanel.querySelectorAll<HTMLButtonElement>("[data-path]").forEach(button => button.addEventListener("click", () => {
  realmHuntPath = button.dataset.path ?? "all";
  realmHuntPanel.querySelectorAll("[data-path]").forEach(candidate => candidate.classList.toggle("active", candidate === button));
  if (button.dataset.contract) room?.send("realm-hunt:board", { action: "contract", pathId: button.dataset.contract, difficulty: realmHuntDifficulty });
  if (latestRealmHuntBoard) renderRealmHuntBoard(latestRealmHuntBoard);
}));
realmHuntPanel.querySelectorAll<HTMLButtonElement>("[data-hunt-difficulty]").forEach(button => button.addEventListener("click", () => {
  realmHuntDifficulty = button.dataset.huntDifficulty as RealmHuntDifficulty;
  realmHuntPanel.querySelectorAll("[data-hunt-difficulty]").forEach(candidate => candidate.classList.toggle("active", candidate === button));
  renderRealmHuntRewardTier();
}));
renderRealmHuntRewardTier();
window.setInterval(() => {
  if (!realmHuntPanel.hidden) room?.send("realm-hunt:board", { action: "sync" });
}, 3_000);

const dungeonLobbyPanel = document.createElement("section");
dungeonLobbyPanel.id = "dungeon-lobby-panel";
dungeonLobbyPanel.hidden = true;
dungeonLobbyPanel.setAttribute("role", "dialog");
dungeonLobbyPanel.setAttribute("aria-label", "Forest dungeon party ready check");
dungeonLobbyPanel.innerHTML = '<small>FOREST DUNGEON</small><h2>EXPEDITION ASSEMBLY</h2><p class="dungeon-lobby-message"></p><ul class="dungeon-lobby-members"></ul><div class="dungeon-lobby-scaling"></div><div class="dungeon-lobby-actions"><button class="dungeon-ready" type="button">READY</button><button class="dungeon-start" type="button">START EXPEDITION</button></div>';
document.body.append(dungeonLobbyPanel);
function renderDungeonLobby(update: DungeonLobbyUpdate): void {
  if (update.phase === "active") { dungeonLobbyPanel.hidden = true; return; }
  dungeonLobbyPanel.hidden = false; resetMovementControls();
  dungeonLobbyPanel.querySelector(".dungeon-lobby-message")!.textContent = update.message;
  const members = dungeonLobbyPanel.querySelector(".dungeon-lobby-members")!; members.replaceChildren();
  for (const member of update.members) {
    const row = document.createElement("li");
    row.className = member.ready ? "ready" : member.entered ? "entered" : "outside";
    row.innerHTML = `<strong>${member.name}</strong><span>${member.ready ? "READY" : member.entered ? "AT ENTRANCE" : "OUTSIDE"}</span>`;
    members.append(row);
  }
  dungeonLobbyPanel.querySelector(".dungeon-lobby-scaling")!.textContent = `Combat scales to players present when the run begins. Current entry: ${update.members.filter(member => member.entered).length}.`;
  const self = update.members.find(member => member.id === room?.sessionId);
  const ready = dungeonLobbyPanel.querySelector<HTMLButtonElement>(".dungeon-ready")!;
  ready.disabled = !self?.entered || Boolean(self.ready); ready.textContent = self?.ready ? "READY ✓" : "READY";
  const start = dungeonLobbyPanel.querySelector<HTMLButtonElement>(".dungeon-start")!;
  start.hidden = !update.leader; start.disabled = !update.members.some(member => member.entered);
}
dungeonLobbyPanel.querySelector(".dungeon-ready")!.addEventListener("click", () => room?.send("dungeon:lobby", { action: "ready" }));
dungeonLobbyPanel.querySelector(".dungeon-start")!.addEventListener("click", () => room?.send("dungeon:lobby", { action: "start" }));

const silverDepthsLobbyPanel = document.createElement("section");
silverDepthsLobbyPanel.id = "silver-depths-lobby-panel";
silverDepthsLobbyPanel.hidden = true;
silverDepthsLobbyPanel.setAttribute("role", "dialog");
silverDepthsLobbyPanel.setAttribute("aria-label", "Silver Depths party ready check");
silverDepthsLobbyPanel.innerHTML = '<small>THE SILVER DEPTHS</small><h2>PARTY READY CHECK</h2><p class="dungeon-lobby-message"></p><ul class="dungeon-lobby-members"></ul><div class="dungeon-lobby-actions"><button class="depths-lobby-ready" type="button">READY</button><button class="depths-lobby-cancel" type="button">CANCEL ASSEMBLY</button></div>';
document.body.append(silverDepthsLobbyPanel);
function renderSilverDepthsLobby(update: SilverDepthsLobbyUpdate): void {
  if (update.phase === "closed") {
    silverDepthsLobbyPanel.hidden = true;
    status.textContent = update.message;
    return;
  }
  silverDepthsLobbyPanel.hidden = false;
  resetMovementControls();
  silverDepthsLobbyPanel.querySelector(".dungeon-lobby-message")!.textContent = update.message;
  const list = silverDepthsLobbyPanel.querySelector(".dungeon-lobby-members")!;
  list.replaceChildren();
  for (const member of update.members) {
    const row = document.createElement("li");
    row.className = member.ready ? "ready" : "outside";
    const name = document.createElement("strong"); name.textContent = member.name;
    const state = document.createElement("span"); state.textContent = member.ready ? "READY" : "WAITING";
    row.append(name, state); list.append(row);
  }
  const self = update.members.find(member => member.id === room?.sessionId);
  const ready = silverDepthsLobbyPanel.querySelector<HTMLButtonElement>(".depths-lobby-ready")!;
  ready.disabled = !self || self.ready;
  ready.textContent = self?.ready ? "READY ✓" : "READY";
}
silverDepthsLobbyPanel.querySelector(".depths-lobby-ready")!.addEventListener("click", () => room?.send("depths:lobby", { action: "ready" }));
