function showDungeonRunResult(update: DungeonRunUpdate): void {
  if (update.phase !== "completed") return;
  document.querySelector("#dungeon-completion")?.remove();
  const panel = document.createElement("section");
  panel.id = "dungeon-completion";
  panel.setAttribute("role", "dialog");
  const silverDepths = update.dungeon === "silver-depths";
  const emberVault = update.dungeon === "ember-vault";
  panel.dataset.dungeon = silverDepths ? "silver-depths" : emberVault ? "ember-vault" : "forest";
  panel.setAttribute("aria-label", silverDepths ? "Silver Depths run results" : emberVault ? "Ember Vault run results" : "Forest Dungeon complete");
  panel.innerHTML = emberVault
    ? '<small>EMBER VAULT · FORGE CONQUERED</small><h2>FORGE COLOSSUS DEFEATED</h2><div class="dungeon-rank"></div><p class="dungeon-run-time"></p><div class="dungeon-stat-grid"><span><small>ENEMIES</small><b data-stat="enemies">0</b></span><span><small>DAMAGE TAKEN</small><b data-stat="damage">0</b></span><span><small>EMBER CORES</small><b data-stat="ember">0</b></span><span><small>CORES HELD</small><b data-stat="wallet">0</b></span><span><small>FORGE LOOT</small><b data-stat="relic">SECURED</b></span></div><strong class="dungeon-run-reward"></strong><p class="dungeon-best-time">The return portal is stable. Collect the Colossus loot before leaving.</p><div class="dungeon-result-actions"><button class="dungeon-return" type="button">CONTINUE</button><button class="dungeon-replay" type="button">RUN AGAIN</button></div>'
    : silverDepths
    ? '<small>SILVER DEPTHS · EXPEDITION COMPLETE</small><h2>CRYSTAL MATRIARCH DEFEATED</h2><div class="dungeon-rank"></div><p class="dungeon-run-time"></p><div class="dungeon-stat-grid"><span><small>ENEMIES</small><b data-stat="enemies">0</b></span><span><small>DAMAGE TAKEN</small><b data-stat="damage">0</b></span><span><small>MOONSTONE AWARD</small><b data-stat="moonstone">0</b></span><span><small>MOONSTONE HELD</small><b data-stat="wallet">0</b></span><span><small>RELIC</small><b data-stat="relic">SECURED</b></span></div><strong class="dungeon-run-reward"></strong><p class="dungeon-best-time"></p><div class="dungeon-result-actions"><button class="dungeon-return" type="button">RETURN TO TOWN</button><button class="dungeon-replay" type="button">RUN AGAIN</button></div>'
    : '<small>FOREST DUNGEON</small><h2>ROOT GUARDIAN DEFEATED</h2><p class="dungeon-run-time"></p><strong class="dungeon-run-reward"></strong><p>Collect your personal equipment bag, then take the return portal.</p><button class="dungeon-return" type="button">CONTINUE</button>';
  const seconds = Math.max(1, Math.round((update.durationMs ?? 0) / 1000));
  panel.querySelector(".dungeon-run-time")!.textContent = `${update.partySize > 1 ? `${update.partySize}-player party` : "Solo clear"} · ${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
  panel.querySelector(".dungeon-run-reward")!.textContent = update.reward ?? "Personal reward unlocked";
  if (silverDepths || emberVault) {
    const stats = update.stats;
    panel.dataset.rank = (update.rank ?? "BRONZE").toLowerCase();
    panel.querySelector(".dungeon-rank")!.textContent = `${update.rank ?? "BRONZE"} RANK`;
    panel.querySelector<HTMLElement>('[data-stat="enemies"]')!.textContent = String(stats?.enemiesDefeated ?? 0);
    panel.querySelector<HTMLElement>('[data-stat="damage"]')!.textContent = String(stats?.damageTaken ?? 0);
    if (emberVault) {
      panel.querySelector<HTMLElement>('[data-stat="ember"]')!.textContent = `+${stats?.emberCoresAwarded ?? 0}`;
      panel.querySelector<HTMLElement>('[data-stat="wallet"]')!.textContent = String(stats?.emberCoresTotal ?? 0);
    } else {
      panel.querySelector<HTMLElement>('[data-stat="moonstone"]')!.textContent = `+${stats?.moonstoneAwarded ?? stats?.moonstoneCollected ?? 0} ◆`;
      panel.querySelector<HTMLElement>('[data-stat="wallet"]')!.textContent = `${stats?.moonstoneTotal ?? 0} ◆`;
    }
    panel.querySelector<HTMLElement>('[data-stat="relic"]')!.textContent = stats?.signatureItemObtained ? "OBTAINED" : "SECURED";
    if (silverDepths) {
      const best = Math.max(1, Math.round((update.bestTimeMs ?? update.durationMs ?? 0) / 1000));
      panel.querySelector(".dungeon-best-time")!.textContent = `${update.newBest ? "NEW PERSONAL BEST" : "PERSONAL BEST"} · ${Math.floor(best / 60)}:${String(best % 60).padStart(2, "0")}`;
    }
    panel.querySelector<HTMLButtonElement>(".dungeon-replay")!.addEventListener("click", event => {
      const button = event.currentTarget as HTMLButtonElement; button.disabled = true; button.textContent = "OPENING PORTAL…";
      setTimeout(() => { panel.remove(); room?.send("portal:use", { id: emberVault ? "ember-entry" : "depths-entry" }); }, 1050);
    });
  }
  panel.querySelector<HTMLButtonElement>(".dungeon-return")!.addEventListener("click", () => panel.remove());
  document.body.append(panel);
}

const characterCreationRequired = (() => {
  const query = new URLSearchParams(window.location.search);
  if (query.has("room") || query.has("returnFrom") || query.has("qa")) return false;
  try { return characterCreationNeeded(window.localStorage); } catch { return true; }
})();
const profileToken = browserProfileToken();
const firstSteps = document.querySelector<HTMLElement>("#first-steps")!;
const firstStepsCount = document.querySelector<HTMLElement>("#first-steps-count")!;
const firstStepsTitle = document.querySelector<HTMLElement>("#first-steps-title")!;
const firstStepsDetail = document.querySelector<HTMLElement>("#first-steps-detail")!;
const firstStepsSkip = document.querySelector<HTMLButtonElement>("#first-steps-skip")!;
const starterInventoryTutorial = document.querySelector<HTMLElement>("#starter-inventory-tutorial")!;
const starterInventoryEyebrow = document.querySelector<HTMLElement>("#starter-inventory-eyebrow")!;
const starterInventoryTitle = document.querySelector<HTMLElement>("#starter-inventory-title")!;
const starterInventoryCopy = document.querySelector<HTMLElement>("#starter-inventory-copy")!;
const modeSwitchTutorial = document.querySelector<HTMLElement>("#mode-switch-tutorial")!;
const modeSwitchTutorialAction = document.querySelector<HTMLButtonElement>("#mode-switch-tutorial-action")!;
const modeSwitchTutorialBuild = document.querySelector<HTMLButtonElement>("#mode-switch-tutorial-build")!;
const modeSwitchTutorialTitle = document.querySelector<HTMLElement>("#mode-switch-tutorial-title")!;
const modeSwitchTutorialCopy = document.querySelector<HTMLElement>("#mode-switch-tutorial-copy")!;
let townDeparturePromptOpen = false;
let modeLessonAcknowledged = false;
let lowLevelWasInsideTown = false;
let lowLevelTownStateReady = false;
let starterInventoryOpenedWithKeyboard = false;
const starterEquipmentKey = starterEquipmentStorageKey(profileToken);
let forcedStarterEquipment = (() => {
  try { return window.localStorage.getItem(starterEquipmentKey) === "required"; }
  catch { return false; }
})();
let tutorialCallingId: BuildPathId | null = null;
let firstCombatPhase: FirstCombatPhase = "attack";
const defeatedFirstCombatMobs = new Set<string>();
const firstStepsKey = onboardingStorageKey(profileToken);
let firstStepsIndex = (() => {
  try {
    const current = parseOnboardingStep(window.localStorage.getItem(firstStepsKey));
    if (current !== null) return current;
    const previous = migrateLegacyOnboardingStep(window.localStorage.getItem(legacyOnboardingStorageKey(profileToken)));
    if (previous !== null) window.localStorage.setItem(firstStepsKey, String(previous));
    if (previous !== null) return previous;
    const oldest = migrateOldestOnboardingStep(window.localStorage.getItem(oldestOnboardingStorageKey(profileToken)));
    if (oldest !== null) window.localStorage.setItem(firstStepsKey, String(oldest));
    return oldest;
  } catch { return null; }
})();
const callingFirstOnboardingKey = callingFirstOnboardingStorageKey(profileToken);
let callingFirstOnboardingPending = shouldDeferOnboardingForCalling(
  characterCreationRequired,
  (() => { try { return window.localStorage.getItem(callingFirstOnboardingKey); } catch { return null; } })(),
  firstStepsIndex,
);
const firstVictoryRewardKey = firstVictoryRewardStorageKey(profileToken);
let firstVictoryReward: FirstVictoryRewardState | null = (() => {
  try {
    const saved = parseFirstVictoryReward(window.localStorage.getItem(firstVictoryRewardKey));
    return saved && isItemId(saved.itemId) ? saved : null;
  } catch { return null; }
})();
function saveFirstVictoryReward(next: FirstVictoryRewardState): void {
  firstVictoryReward = next;
  try { window.localStorage.setItem(firstVictoryRewardKey, JSON.stringify(next)); }
  catch { /* Private browsing can disable storage. */ }
  renderFirstSteps();
}
function firstVictoryRewardLessonReady(): boolean {
  return firstStepsIndex !== null && firstStepsIndex >= ONBOARDING_DONE;
}
function beginFirstVictoryReward(itemId: ItemId): void {
  if (firstVictoryReward?.stage === "complete" || firstVictoryReward?.stage === "return_town") return;
  saveFirstVictoryReward({ stage: "open_pack", itemId });
  status.textContent = firstVictoryRewardLessonReady()
    ? `Calling-matched reward collected · press I to compare ${ITEM_DEFINITIONS[itemId].name}.`
    : `${ITEM_DEFINITIONS[itemId].name} secured · finish the remaining enemies, then inspect your reward.`;
}
function completeFirstVictoryDecision(choice: "equipped" | "kept"): void {
  if (!firstVictoryReward || firstVictoryReward.stage !== "choose") return;
  const itemName = ITEM_DEFINITIONS[firstVictoryReward.itemId as ItemId]?.name ?? "Your reward";
  saveFirstVictoryReward({ ...firstVictoryReward, stage: "return_town" });
  firstStepsTrailUpdatedAt = -Infinity;
  if (!inventoryPanel.hidden) setInventoryOpen(false);
  status.textContent = `${itemName} ${choice} · follow the gold trail back to Town.`;
  social.event(`${itemName} ${choice} · return to Town to awaken your first ability.`);
}
function completeFirstVictoryReturn(): void {
  if (!firstVictoryReward || firstVictoryReward.stage !== "return_town") return;
  saveFirstVictoryReward({ ...firstVictoryReward, stage: "complete" });
  status.textContent = "Returned to Town · your first Calling ability is ready to reveal.";
  social.event("Returned to Town · Calling ability ready.");
}
function renderFirstSteps(): void {
  const index = firstStepsIndex;
  const onboardingActive = !callingFirstOnboardingPending && index !== null && index < ONBOARDING_DONE;
  const rewardActive = firstVictoryRewardLessonReady()
    && Boolean(firstVictoryReward && firstVictoryReward.stage !== "complete");
  const active = onboardingActive || rewardActive;
  const modeLesson = index === ONBOARDING_STAGE.chooseMode;
  firstSteps.hidden = !active;
  firstSteps.dataset.guidance = firstVictoryReward?.stage === "return_town" ? "return-town"
    : index === ONBOARDING_STAGE.headSouth ? "south-gate" : "";
  const starterLesson = starterInventoryLesson(index, starterInventoryOpenedWithKeyboard, forcedStarterEquipment, localMainHandId);
  const rewardInventoryLesson = rewardActive && (firstVictoryReward?.stage === "open_pack" || firstVictoryReward?.stage === "choose")
    ? firstVictoryReward.stage : null;
  firstStepsSkip.hidden = rewardActive || modeLesson || starterLesson !== "hidden";
  const showModeChoice = townDeparturePromptOpen || modeLesson && !modeLessonAcknowledged;
  modeSwitchTutorial.hidden = !showModeChoice;
  modeSwitchTutorialTitle.textContent = "Choose how to leave Town";
  modeSwitchTutorialCopy.innerHTML = "<b>BUILD</b> gathers resources. <b>COMBAT</b> attacks enemies. Press <kbd>Q</kbd> at any time to switch.";
  document.documentElement.classList.toggle("onboarding-active", active);
  document.documentElement.classList.toggle("onboarding-mode-lesson", modeLesson);
  document.documentElement.classList.toggle("first-combat-attack", index === ONBOARDING_STAGE.firstCombat && firstCombatPhase === "attack");
  document.documentElement.classList.toggle("first-combat-dodge", index === ONBOARDING_STAGE.firstCombat && firstCombatPhase === "dodge");
  document.documentElement.classList.toggle("first-combat-finish", index === ONBOARDING_STAGE.firstCombat && firstCombatPhase === "finish");
  starterInventoryTutorial.hidden = starterLesson === "hidden" && rewardInventoryLesson === null;
  starterInventoryTutorial.dataset.phase = rewardInventoryLesson === "choose" || starterLesson === "equip_sword" ? "equip_sword" : "open_pack";
  starterInventoryEyebrow.textContent = rewardInventoryLesson ? "FIRST VICTORY REWARD" : "STARTER EQUIPMENT";
  const rewardName = firstVictoryReward && isItemId(firstVictoryReward.itemId)
    ? ITEM_DEFINITIONS[firstVictoryReward.itemId].name : "Calling upgrade";
  starterInventoryTitle.textContent = rewardInventoryLesson === "choose" ? `Choose what to do with ${rewardName}`
    : rewardInventoryLesson === "open_pack" ? "Open your pack"
      : starterLesson === "equip_sword" ? "Equip the Forged Sword" : "Open your inventory";
  starterInventoryCopy.textContent = rewardInventoryLesson === "choose"
    ? "Compare the glowing reward, then choose EQUIP UPGRADE or KEEP FOR LATER. Either choice completes this lesson."
    : rewardInventoryLesson === "open_pack" ? `Press I to compare ${rewardName}, your first Calling-matched reward.`
      : starterLesson === "equip_sword"
        ? "Select the glowing sword, then choose EQUIP. This lesson completes only when the sword is equipped."
        : "Starter bag collected. Press I to open your inventory, then select and equip the Forged Sword.";
  const starterCard = document.querySelector<HTMLElement>('[data-item="forged_sword"]');
  if (starterCard) starterCard.dataset.starterTutorial = starterLesson === "equip_sword" ? "true" : "false";
  for (const card of document.querySelectorAll<HTMLElement>("#inventory-panel article.equipment[data-item]"))
    card.dataset.firstVictoryReward = String(rewardInventoryLesson === "choose" && card.dataset.item === firstVictoryReward?.itemId);
  if (rewardActive && firstVictoryReward) {
    firstStepsCount.textContent = "REWARD";
    if (firstVictoryReward.stage === "open_pack") {
      firstStepsTitle.textContent = "Inspect your first victory reward";
      firstStepsDetail.textContent = `Press I to compare ${rewardName}. It was selected for your Calling.`;
    } else if (firstVictoryReward.stage === "choose") {
      firstStepsTitle.textContent = `Equip or keep ${rewardName}`;
      firstStepsDetail.textContent = "Choose EQUIP UPGRADE or KEEP FOR LATER in the comparison panel.";
    } else {
      firstStepsTitle.textContent = "Return to Town";
      firstStepsDetail.textContent = "Follow the gold trail back to the Town of Beginnings to reveal your new ability.";
    }
    return;
  }
  if (index === null || index >= ONBOARDING_DONE) return;
  const step = ONBOARDING_STEPS[index]!;
  firstStepsCount.textContent = `${index + 1} / ${ONBOARDING_DONE}`;
  const combatLesson = index === ONBOARDING_STAGE.firstCombat ? firstCombatLesson(tutorialCallingId, firstCombatPhase) : null;
  firstStepsTitle.textContent = combatLesson?.title ?? step.title;
  firstStepsDetail.textContent = combatLesson?.detail ?? step.detail;
}
function setFirstSteps(index: number): void {
  firstStepsIndex = index;
  try { window.localStorage.setItem(firstStepsKey, String(index)); } catch { /* Private browsing can disable storage. */ }
  renderFirstSteps();
}
function beginFirstStepsAfterCalling(): void {
  if (!callingFirstOnboardingPending) return;
  callingFirstOnboardingPending = false;
  try { window.localStorage.removeItem(callingFirstOnboardingKey); } catch { /* Storage may be unavailable. */ }
  setFirstSteps(0);
  status.textContent = "Calling chosen · follow the gold trail to your personal starter bag.";
  syncProtectedDialog();
}
function noteFirstStep(event: OnboardingEvent): void {
  if (firstStepsIndex === null || firstStepsIndex >= ONBOARDING_DONE) return;
  const next = advanceOnboarding(firstStepsIndex, event);
  if (next === firstStepsIndex) return;
  if (next === ONBOARDING_STAGE.firstCombat) {
    firstCombatPhase = "attack";
    defeatedFirstCombatMobs.clear();
  }
  setFirstSteps(next);
  if (next === ONBOARDING_STAGE.headSouth) {
    firstStepsTrailUpdatedAt = -Infinity;
    firstSteps.classList.remove("route-started");
    void firstSteps.offsetWidth;
    firstSteps.classList.add("route-started");
    window.setTimeout(() => firstSteps.classList.remove("route-started"), 1_100);
    status.textContent = "Starter gear equipped · follow the gold trail to the SOUTH GATE.";
    social.event("Starter gear equipped · follow the gold trail to the South Gate.");
  }
  if (next === ONBOARDING_DONE) status.textContent = "First steps complete · follow Realm Guidance or explore freely.";
}
function nudgeStarterInventoryTutorial(): void {
  starterInventoryTutorial.classList.remove("nudge");
  void starterInventoryTutorial.offsetWidth;
  starterInventoryTutorial.classList.add("nudge");
  window.setTimeout(() => starterInventoryTutorial.classList.remove("nudge"), 420);
}
function requireStarterEquipment(): void {
  if (localMainHandId === "forged_sword") return;
  forcedStarterEquipment = true;
  starterInventoryOpenedWithKeyboard = false;
  try { window.localStorage.setItem(starterEquipmentKey, "required"); } catch { /* Storage may be unavailable. */ }
  renderFirstSteps();
}
function completeStarterEquipment(): void {
  forcedStarterEquipment = false;
  try { window.localStorage.setItem(starterEquipmentKey, "complete"); } catch { /* Storage may be unavailable. */ }
  renderFirstSteps();
}
