function applyDefensePose(rig: VoxelCharacterRig): void {
  rig.torso.setLocalEulerAngles(7, 0, 0);
  rig.leftArm.setLocalEulerAngles(-82, 0, -32);
  rig.rightArm.setLocalEulerAngles(-68, 0, 28);
}

