function coloredMaterial(color: pc.Color): pc.StandardMaterial {
  const material = new pc.StandardMaterial();
  material.diffuse = color;
  material.update();
  return material;
}

const distantMobMaterials = new Map<string, pc.StandardMaterial>();
function distantMobMaterial(color: pc.Color): pc.StandardMaterial {
  const key = `${color.r.toFixed(3)}:${color.g.toFixed(3)}:${color.b.toFixed(3)}`;
  const existing = distantMobMaterials.get(key);
  if (existing) return existing;
  const material = coloredMaterial(color.clone());
  material.shininess = 8;
  material.update();
  distantMobMaterials.set(key, material);
  return material;
}

function createMidDetailMob(archetype: string, color: pc.Color, scale: number): pc.Entity {
  const root = new pc.Entity("mob-middle-detail");
  const material = distantMobMaterial(color);
  for (const part of mobMidDetailParts(archetype)) {
    const entity = new pc.Entity(part.name);
    entity.addComponent("render", {
      type: "box", material, castShadows: false, receiveShadows: true,
      batchGroupId: distantMobBatchGroup.id,
    });
    entity.setLocalPosition(...part.at);
    entity.setLocalScale(...part.size);
    if (part.angle) entity.setLocalEulerAngles(...part.angle);
    root.addChild(entity);
  }
  root.setLocalScale(scale, scale, scale);
  root.enabled = false;
  return root;
}

function batchCloseMobArt(root: pc.Entity, rig: MobArtRig): void {
  // Materials on these pieces are swapped at runtime to communicate enraged and defeated states.
  // Keep them independent while batching all other articulated rig surfaces dynamically.
  const independent = new Set<pc.Entity>([
    ...rig.phaseSurfaces,
    ...rig.glowSurfaces.map(surface => surface.part),
  ]);
  for (const component of root.findComponents("render")) {
    const render = component as pc.RenderComponent;
    if (!independent.has(render.entity as pc.Entity)) render.batchGroupId = closeMobBatchGroup.id;
  }
}

