  const ashRock = coloredMaterial(new pc.Color(.25, .22, .22));
  const lava = new pc.StandardMaterial();
  lava.diffuse = new pc.Color(.95, .19, .035);
  lava.emissive = new pc.Color(.8, .07, .01);
  lava.update();
  const greenwoodMoteMaterial = new pc.StandardMaterial();
  greenwoodMoteMaterial.diffuse = new pc.Color(.76, 1, .42);
  greenwoodMoteMaterial.emissive = new pc.Color(.35, .78, .08);
  greenwoodMoteMaterial.useLighting = false;
  greenwoodMoteMaterial.blendType = pc.BLEND_ADDITIVE;
  greenwoodMoteMaterial.depthWrite = false;
  greenwoodMoteMaterial.update();
  const greenwoodCorruption = new pc.StandardMaterial();
  greenwoodCorruption.diffuse = new pc.Color(.28, .09, .32);
  greenwoodCorruption.emissive = new pc.Color(.12, .015, .18);
  greenwoodCorruption.gloss = .24;
  greenwoodCorruption.update();
  const greenwoodEmber = new pc.StandardMaterial();
  greenwoodEmber.diffuse = new pc.Color(1, .34, .055);
  greenwoodEmber.emissive = new pc.Color(.8, .1, .01);
  greenwoodEmber.useLighting = false;
  greenwoodEmber.update();
  for (const [material, opacity] of [[townMeadowOverlay, .28], [townVergeOverlay, .34], [roadWearOverlay, .18],
    [greenwoodMoss, .54], [greenwoodLeafLitter, .64]] as const) {
    material.opacity = opacity;
    material.blendType = pc.BLEND_NORMAL;
    material.depthWrite = false;
    material.update();
  }
  const townPollenMaterial = new pc.StandardMaterial();
  townPollenMaterial.diffuse = new pc.Color(1, .82, .36);
  townPollenMaterial.emissive = new pc.Color(.38, .2, .035);
  townPollenMaterial.useLighting = false;
  townPollenMaterial.blendType = pc.BLEND_ADDITIVE;
  townPollenMaterial.depthWrite = false;
  townPollenMaterial.update();
  const townLeafMaterial = new pc.StandardMaterial();
  townLeafMaterial.diffuse = new pc.Color(.54, .36, .12);
  townLeafMaterial.opacity = .82;
  townLeafMaterial.blendType = pc.BLEND_NORMAL;
  townLeafMaterial.depthWrite = false;
  townLeafMaterial.update();
  const townWaterMaterial = new pc.StandardMaterial();
  townWaterMaterial.diffuse = new pc.Color(.18, .55, .63);
  townWaterMaterial.emissive = new pc.Color(.02, .12, .15);
  townWaterMaterial.opacity = .84;
  townWaterMaterial.blendType = pc.BLEND_NORMAL;
  townWaterMaterial.gloss = .65;
  townWaterMaterial.update();
  const rapidRegionGroundMaterials: Record<FastWorldVisualTheme, pc.StandardMaterial> = {
    forest: greenwoodGround,
    marsh: mistfenGround,
    coast: coastGround,
    quarry: quarryGround,
    volcanic: ashenGround,
  };

  const addTownShape = (parent: pc.Entity, name: string, type: "box" | "cylinder" | "cone" | "sphere",
    material: pc.StandardMaterial, scale: [number, number, number], position: [number, number, number]): pc.Entity => {
    const shape = new pc.Entity(name);
    shape.addComponent("render", { type, castShadows: true });
    if (shape.render) shape.render.material = material;
    if (type === "box") fitGroundTexture(app.graphicsDevice, shape, material, scale, position);
    shape.setLocalScale(...scale);
    shape.setLocalPosition(...position);
    parent.addChild(shape);
    return shape;
  };
  const addRapidWorldShape = (name: string, type: "box" | "cylinder" | "cone" | "sphere",
    material: pc.StandardMaterial, scale: [number, number, number], position: [number, number, number]): pc.Entity => {
    const shape = addTownShape(rapidPrototypeRoot, name, type, material, scale, position);
    if (shape.render) shape.render.batchGroupId = rapidWorldSceneryBatchGroup.id;
    return shape;
  };
  const addRapidWorldBox = (name: string, material: pc.StandardMaterial,
    scale: [number, number, number], position: [number, number, number]): pc.Entity => {
    const shape = addBox(rapidPrototypeRoot, name, material, scale, position);
    if (shape.render) shape.render.batchGroupId = rapidWorldSceneryBatchGroup.id;
    return shape;
  };
  const rapidRegionChunkRoots = new Map<string, pc.Entity>();
  const rapidRegionStream = new FastWorldVisualChunkStream(1);
  let activeRapidRegionChunkKeys = fastWorldActiveVisualChunkKeys(99.5, 106.5, 1);
  rapidWorldActiveVisualChunks = activeRapidRegionChunkKeys.size;
  const rapidRegionChunkRoot = (regionId: FastWorldStreamedRegionId, x: number, z: number): pc.Entity => {
    const key = fastWorldVisualChunkForPosition(regionId, x, z);
    const existing = rapidRegionChunkRoots.get(key);
    if (existing) return existing;
    const root = new pc.Entity(`fast-world-region-chunk:${key}`);
    root.enabled = activeRapidRegionChunkKeys.has(key);
    rapidPrototypeRoot.addChild(root);
    rapidRegionChunkRoots.set(key, root);
    rapidWorldTotalVisualChunks = rapidRegionChunkRoots.size;
    return root;
  };
  const addRapidRegionShape = (regionId: FastWorldStreamedRegionId, name: string,
    type: "box" | "cylinder" | "cone" | "sphere", material: pc.StandardMaterial,
    scale: [number, number, number], position: [number, number, number]): pc.Entity => {
    const shape = addTownShape(rapidRegionChunkRoot(regionId, position[0], position[2]), name, type, material, scale, position);
    if (shape.render) shape.render.batchGroupId = rapidWorldSceneryBatchGroup.id;
    return shape;
  };
  const addRapidRegionBox = (regionId: FastWorldStreamedRegionId, name: string, material: pc.StandardMaterial,
    scale: [number, number, number], position: [number, number, number]): pc.Entity => {
    const shape = addBox(rapidRegionChunkRoot(regionId, position[0], position[2]), name, material, scale, position);
    if (shape.render) shape.render.batchGroupId = rapidWorldSceneryBatchGroup.id;
    return shape;
  };
  updateRapidRegionVisualStream = (x: number, z: number): void => {
    const change = rapidRegionStream.update(x, z);
    if (!change) return;
    activeRapidRegionChunkKeys = change.active;
    rapidWorldActiveVisualChunks = change.active.size;
    for (const [key, root] of rapidRegionChunkRoots) root.enabled = activeRapidRegionChunkKeys.has(key);
  };

  const skin = coloredMaterial(new pc.Color(.72, .49, .31));
  const darkHair = coloredMaterial(new pc.Color(.12, .07, .04));
  const warmHair = coloredMaterial(new pc.Color(.23, .1, .045));
  const eyeWhite = coloredMaterial(new pc.Color(.94, .9, .78));
  const faceInk = coloredMaterial(new pc.Color(.055, .035, .025));
  const faceScar = coloredMaterial(new pc.Color(.42, .11, .075));
  const healerGem = coloredMaterial(new pc.Color(.18, .9, .72));
  const trouser = coloredMaterial(new pc.Color(.16, .16, .18));
  const actorMaterials = new Map<string, { coat: pc.StandardMaterial; accent: pc.StandardMaterial }>();
  for (const definition of SPEED_LAB_TOWN_ACTORS) {
    actorMaterials.set(definition.id, {
      coat: coloredMaterial(new pc.Color(...definition.coat)),
      accent: coloredMaterial(new pc.Color(...definition.accent)),
    });
  }
  const npcIrisMaterials = new Map<TownLifeActorDefinition["role"], pc.StandardMaterial>();
  for (const definition of SPEED_LAB_TOWN_ACTORS) {
    if (npcIrisMaterials.has(definition.role)) continue;
    npcIrisMaterials.set(definition.role, coloredMaterial(new pc.Color(...townNpcFaceStyle(definition.role).iris)));
  }
  const addTownLimb = (root: pc.Entity, name: string, pivot: [number, number, number], material: pc.StandardMaterial,
    scale: [number, number, number]): pc.Entity => {
    const limb = new pc.Entity(`${name}-pivot`);
    limb.setLocalPosition(...pivot);
    root.addChild(limb);
    addBox(limb, name, material, scale, [0, -scale[1] * .45, 0]);
    return limb;
  };
  const addTownActor = (definition: TownLifeActorDefinition): void => {
    const materials = actorMaterials.get(definition.id)!;
    const root = new pc.Entity(`town-life:${definition.id}`);
    root.setLocalPosition(definition.route[0]![0], 8.15, definition.route[0]![1]);
    rapidPrototypeRoot.addChild(root);
    const fallback = new pc.Entity("townsperson-procedural-fallback");
    root.addChild(fallback);
    const torso = addBox(fallback, "townsperson-torso", materials.coat, [.48, .68, .3], [0, 1.02, 0]);
    addBox(fallback, "townsperson-belt", materials.accent, [.51, .08, .32], [0, .82, 0]);
    addTownShape(fallback, "townsperson-coat-skirt", "cone", materials.coat, [.42, .38, .34], [0, .72, 0]);
    const head = addTownShape(fallback, "townsperson-head", "sphere", skin, [.34, .39, .34], [0, 1.61, 0]);
    addTownShape(fallback, "townsperson-hair", "sphere", darkHair, [.36, .16, .36], [0, 1.79, -.02]);
    const faceStyle = townNpcFaceStyle(definition.role);
    const iris = npcIrisMaterials.get(definition.role)!;
    for (const side of [-1, 1] as const) {
      addTownShape(head, `fallback-eye-white-${side}`, "sphere", eyeWhite, [.2, .115, .07], [side * .36, .12, .93]);
      addTownShape(head, `fallback-iris-${side}`, "sphere", iris, [.09, .09, .04], [side * .36, .12, 1.01]);
      addTownShape(head, `fallback-pupil-${side}`, "sphere", faceInk, [.038, .05, .025], [side * .36, .12, 1.06]);
      addTownShape(head, `fallback-brow-${side}`, "box", faceInk, [.23, .05, .045], [side * .36, .38, .98])
        .setLocalEulerAngles(0, 0, side * faceStyle.browTilt);
    }
    addTownShape(head, "fallback-nose", "sphere", skin, [.13, .22, .12], [0, -.08, 1.02]);
    addTownShape(head, "fallback-mouth", "box", faceInk, [.32, .05, .04], [0, -.37, 1]);
    const leftArm = addTownLimb(fallback, "townsperson-left-arm", [-.33, 1.25, 0], materials.coat, [.17, .54, .2]);
    const rightArm = addTownLimb(fallback, "townsperson-right-arm", [.33, 1.25, 0], materials.coat, [.17, .54, .2]);
    const leftLeg = addTownLimb(fallback, "townsperson-left-leg", [-.14, .72, 0], trouser, [.2, .62, .23]);
    const rightLeg = addTownLimb(fallback, "townsperson-right-leg", [.14, .72, 0], trouser, [.2, .62, .23]);
    if (definition.role === "guard") {
      addBox(torso, "warden-breastplate", materials.accent, [.34, .34, .045], [0, .02, .175]);
      addTownShape(leftArm, "warden-shield", "cylinder", materials.accent, [.34, .08, .34], [0, -.3, .2])
        .setLocalEulerAngles(90, 0, 0);
    } else if (definition.role === "vendor") {
      addBox(torso, "vendor-apron", materials.accent, [.38, .48, .04], [0, -.02, .175]);
    } else if (definition.role === "smith") {
      addBox(torso, "smith-apron", materials.accent, [.39, .5, .045], [0, -.03, .18]);
      addBox(rightArm, "smith-hammer-grip", timber, [.09, .55, .09], [0, -.42, 0]);
      addBox(rightArm, "smith-hammer-head", iron, [.46, .18, .2], [0, -.72, 0]);
    } else if (definition.role === "healer") {
      addBox(torso, "healer-cross-vertical", materials.accent, [.08, .3, .04], [0, .02, .18]);
      addBox(torso, "healer-cross-horizontal", materials.accent, [.25, .08, .04], [0, .02, .18]);
    }
    rapidTownActors.push({ definition, root, fallback, model: null, animationName: "", torso, head,
      leftArm, rightArm, leftLeg, rightLeg });
  };
  SPEED_LAB_TOWN_ACTORS.forEach(addTownActor);

  const townNpcAccessories = new Set(["1H_Sword_Offhand", "Badge_Shield", "Rectangle_Shield", "Round_Shield",
    "Spike_Shield", "1H_Sword", "2H_Sword", "Knife_Offhand", "1H_Crossbow", "2H_Crossbow", "Knife",
    "Throwable", "1H_Axe_Offhand", "Barbarian_Round_Shield", "1H_Axe", "2H_Axe", "Mug", "Spellbook",
    "Spellbook_open", "1H_Wand", "2H_Staff"]);
  const visibleNpcAccessories: Readonly<Record<TownLifeActorDefinition["role"], ReadonlySet<string>>> = {
    guard: new Set(["Round_Shield", "1H_Sword"]),
    healer: new Set(["Spellbook_open", "1H_Wand"]),
    vendor: new Set(), smith: new Set(), resident: new Set(),
  };
  const addTownFaceShape = (parent: pc.Entity, name: string, type: "box" | "sphere",
    material: pc.StandardMaterial, scale: [number, number, number], position: [number, number, number],
    euler?: [number, number, number]): pc.Entity => {
    const shape = new pc.Entity(name);
    shape.addComponent("render", { type, castShadows: false, receiveShadows: false,
      batchGroupId: townNpcFaceBatchGroup.id });
    if (shape.render) shape.render.material = material;
    shape.setLocalScale(...scale);
    shape.setLocalPosition(...position);
    if (euler) shape.setLocalEulerAngles(...euler);
    parent.addChild(shape);
    return shape;
  };
  const addTownNpcMouth = (head: pc.Entity, expression: TownNpcMouthExpression): void => {
    if (expression === "calm" || expression === "stern") {
      addTownFaceShape(head, `npc-mouth-${expression}`, "box", faceInk,
        [expression === "stern" ? .15 : .12, .022, .018], [0, .265, .535]);
      return;
    }
    addTownFaceShape(head, "npc-smile-left", "box", faceInk, [.075, .022, .018], [-.06, .282, .535], [0, 0, -12]);
    addTownFaceShape(head, "npc-smile-right", "box", faceInk, [.075, .022, .018], [.06, .282, .535], [0, 0, 12]);
  };
  const addTownNpcFace = (actor: RapidTownActorVisual, model: pc.Entity): void => {
    const head = model.findByName("head") as pc.Entity | null;
    if (!head) {
      console.warn(`[town-npcs] ${actor.definition.role} model has no animated head bone for facial details.`);
      return;
    }
    const style = townNpcFaceStyle(actor.definition.role);
    const iris = npcIrisMaterials.get(actor.definition.role)!;
    const face = new pc.Entity(`npc-face:${actor.definition.id}`);
    head.addChild(face);
    for (const side of [-1, 1] as const) {
      const x = side * .16;
      addTownFaceShape(face, `npc-eye-white-${side}`, "sphere", eyeWhite, [.115, .068, .035], [x, .54, .505]);
      addTownFaceShape(face, `npc-iris-${side}`, "sphere", iris, [.052, .052, .025], [x, .54, .542]);
      addTownFaceShape(face, `npc-pupil-${side}`, "sphere", faceInk, [.021, .028, .014], [x, .54, .565]);
      addTownFaceShape(face, `npc-brow-${side}`, "box", faceInk, [.13, .028, .025],
        [x, .665, .535], [0, 0, side * style.browTilt]);
    }
    addTownFaceShape(face, "npc-nose", "sphere", skin, [.06, .105, .065], [0, .405, .54]);
    addTownNpcMouth(face, style.mouth);

    if (style.scar)
      addTownFaceShape(face, "npc-warden-scar", "box", faceScar, [.018, .115, .017], [.285, .37, .538], [0, 0, -20]);
    if (style.beard) {
      addTownFaceShape(face, "npc-smith-beard", "sphere", warmHair, [.31, .245, .075], [0, .17, .47]);
      addTownFaceShape(face, "npc-smith-moustache-left", "box", warmHair, [.1, .035, .025], [-.08, .31, .555], [0, 0, -10]);
      addTownFaceShape(face, "npc-smith-moustache-right", "box", warmHair, [.1, .035, .025], [.08, .31, .555], [0, 0, 10]);
    }
    if (style.circlet) {
      addTownFaceShape(face, "npc-healer-circlet", "box", bannerGold, [.37, .025, .025], [0, .76, .515]);
      addTownFaceShape(face, "npc-healer-gem", "sphere", healerGem, [.055, .065, .025], [0, .755, .548]);
    }
    if (style.freckles) {
      for (const side of [-1, 1] as const) {
        for (let index = 0; index < 3; index++)
          addTownFaceShape(face, `npc-freckle-${side}-${index}`, "sphere", warmHair, [.014, .014, .01],
            [side * (.205 + index * .032), .37 + (index % 2) * .035, .545]);
      }
    }
  };
  const decorateLoadedTownNpc = (actor: RapidTownActorVisual, model: pc.Entity): void => {
    const visible = visibleNpcAccessories[actor.definition.role];
    for (const node of model.find(candidate => townNpcAccessories.has(candidate.name))) node.enabled = visible.has(node.name);
    addTownNpcFace(actor, model);
    if (actor.definition.role !== "smith") return;
    const hand = model.findByName("handslot.r") as pc.Entity | null;
    if (!hand) return;
    const handle = addBox(hand, "smith-hammer-handle", timber, [.07, .42, .07], [0, -.18, 0]);
    handle.setLocalEulerAngles(0, 0, 8);
    const hammer = addBox(hand, "smith-hammer-head", iron, [.34, .14, .16], [0, -.45, 0]);
    hammer.setLocalEulerAngles(0, 0, 8);
  };
  let townNpcAssetsStarted = false;
  requestRapidTownNpcAssets = (): void => {
    if (townNpcAssetsStarted) return;
    townNpcAssetsStarted = true;
    void loadTownNpcAssets(app).then(result => {
      let animatedActors = 0;
      for (const actor of rapidTownActors) {
        const asset = result.loaded.get(actor.definition.role);
        const resource = asset?.resource as (pc.ContainerResource & { animations: pc.Asset[] }) | undefined;
        if (!resource) continue;
        const model = resource.instantiateRenderEntity({ castShadows: true, receiveShadows: true });
        model.name = `town-npc-model:${actor.definition.role}`;
        model.setLocalScale(.78, .78, .78);
        model.setLocalEulerAngles(0, TOWN_NPC_MODEL_YAW, 0);
        actor.root.addChild(model);
        decorateLoadedTownNpc(actor, model);
        const animationName = townLifeAnimation(actor.definition, townLifeActorPose(actor.definition, performance.now() * .001));
        if (!bindTownNpcRig(model, resource.animations, animationName, actor.definition.phase)) {
          console.warn(`[town-npcs] ${actor.definition.role} rig did not expose playable AnimTracks; retaining fallback.`);
          model.destroy();
          continue;
        }
        actor.model = model;
        actor.animationName = animationName;
        actor.fallback.enabled = false;
        animatedActors++;
      }
      console.info(`[town-npcs] ${animatedActors}/${rapidTownActors.length} animated actors ready; ` +
        `${rapidTownActors.length - animatedActors} procedural fallbacks retained (${result.loaded.size} role assets loaded).`);
    });
  };

  const signSymbol = new pc.StandardMaterial();
  signSymbol.diffuse = new pc.Color(1, .72, .2);
  signSymbol.emissive = new pc.Color(.26, .1, .01);
  signSymbol.update();
  for (const sign of SPEED_LAB_TOWN_SIGNS) {
    const root = new pc.Entity(`town-landmark:${sign.id}`);
    root.setLocalPosition(...sign.position);
    root.setLocalEulerAngles(0, sign.yaw, 0);
    rapidPrototypeRoot.addChild(root);
    addTownShape(root, "landmark-sign-post", "cylinder", timber, [.1, 1.2, .1], [0, .58, 0]);
    addBox(root, "landmark-sign-board", timberLight, [.14, .82, 1.05], [0, 1.45, 0]);
    addBox(root, "landmark-sign-inlay", signSymbol, [.15, .58, .82], [.08, 1.45, 0]);
    if (sign.kind === "healer") {
      addBox(root, "healer-symbol", plasterLight, [.16, .12, .56], [.17, 1.45, 0]);
      addBox(root, "healer-symbol", plasterLight, [.16, .5, .13], [.17, 1.45, 0]);
    } else if (sign.kind === "smith") {
      const handle = addBox(root, "smith-symbol", iron, [.17, .08, .58], [.17, 1.45, 0]);
      handle.setLocalEulerAngles(35, 0, 0);
      const hammer = addBox(root, "smith-symbol", iron, [.18, .18, .42], [.17, 1.66, -.2]);
      hammer.setLocalEulerAngles(35, 0, 0);
    } else if (sign.kind === "inn") {
      addTownShape(root, "inn-symbol", "cylinder", plasterLight, [.26, .16, .26], [.17, 1.44, 0])
        .setLocalEulerAngles(0, 0, 90);
      addBox(root, "inn-symbol-handle", plasterLight, [.16, .26, .09], [.17, 1.45, .28]);
    } else if (sign.kind === "weaver") {
      for (const z of [-.28, 0, .28]) addTownShape(root, "weaver-symbol", "cylinder", z === 0 ? bannerBlue : plasterLight,
        [.16, .13, .16], [.17, 1.45, z]).setLocalEulerAngles(0, 0, 90);
    } else if (sign.kind === "barracks") {
      const shield = addBox(root, "warden-symbol", bannerBlue, [.16, .48, .42], [.17, 1.46, 0]);
      shield.setLocalEulerAngles(0, 0, 45);
    } else {
      addTownShape(root, "hall-symbol", "cylinder", plasterLight, [.28, .12, .28], [.17, 1.45, 0])
        .setLocalEulerAngles(0, 0, 90);
    }
  }

  for (let index = 0; index < SPEED_LAB_TOWN_LIGHTS.length; index++) {
    const [x, y, z] = SPEED_LAB_TOWN_LIGHTS[index]!;
    const light = new pc.Entity(`town-lantern-light-${index + 1}`);
    light.addComponent("light", { type: "omni", color: new pc.Color(1, .63, .25), intensity: 1.1,
      range: 7, castShadows: false });
    light.setLocalPosition(x, y, z);
    rapidPrototypeRoot.addChild(light);
    rapidTownLights.push({ entity: light, phase: index * 1.7 });
  }

  addRapidWorldBox("realm-ground", grass, [220, .25, 172], [150, 7.875, 106]);
  addBox(rapidPrototypeRoot, "west-green", townVerge, [62, .035, 74], [71, 8.02, 106]);
  for (const region of FAST_WORLD_REGION_DEFINITIONS) {
    const regionId = region.id as FastWorldStreamedRegionId;
    for (const chunk of fastWorldRegionVisualChunks(regionId))
      addRapidRegionBox(regionId, `${regionId}-ground:${chunk.key}`, rapidRegionGroundMaterials[region.visualTheme],
        [chunk.width, .035, chunk.depth], [chunk.centerX, 8.02, chunk.centerZ]);
  }
  addRapidWorldBox("east-realm-road", path, [154, .055, 5.2], [179, 8.035, 106]);
  addRapidWorldBox("regional-fork-road", path, [5.2, .06, 130], [168, 8.04, 106]);
  addRapidWorldBox("mistfen-road", roadWarm, [28, .055, 4.2], [181, 8.045, 65]);
  addRapidWorldBox("quarry-road", roadWarm, [28, .055, 4.2], [181, 8.045, 151]);
  addRapidWorldBox("coast-road", roadWarm, [4.2, .055, 48], [100, 8.045, 166]);
  addRapidWorldBox("realm-crossroads", stone, [9.5, .09, 9.5], [168, 8.075, 106]);
  for (const patch of GREENWOOD_GROUND_PATCHES) {
    const material = patch.material === "moss" ? greenwoodMoss : greenwoodLeafLitter;
    const groundPatch = addRapidRegionShape("greenwood", `greenwood-ground:${patch.id}`, "cylinder", material,
      [patch.scale[0], .025, patch.scale[1]], [patch.position[0], 8.105, patch.position[1]]);
    groundPatch.setLocalEulerAngles(0, patch.yaw, 0);
  }
  for (const mound of GREENWOOD_ELEVATION_MOUNDS) {
    const bank = addRapidRegionShape("greenwood", `greenwood-bank:${mound.id}`, "cylinder", greenwoodMoss,
      [mound.width, mound.height, mound.depth], [mound.x, 8.01 + mound.height * .36, mound.z]);
    bank.setLocalEulerAngles(0, mound.yaw, 0);
  }

  // The town now fades into Greenwood through layered verge, moss and leaf
  // textures. These shallow shapes communicate terrain without lying about
  // the server-owned collision plane.
  for (const patch of TOWN_ATMOSPHERE_PATCHES) {
    const material = patch.material === "meadow" ? townMeadowOverlay
      : patch.material === "verge" ? townVergeOverlay
      : patch.material === "roadWear" ? roadWearOverlay
      : patch.material === "moss" ? greenwoodMoss : greenwoodLeafLitter;
    const scale: [number, number, number] = [patch.scale[0], .018, patch.scale[1]];
    const position: [number, number, number] = [patch.position[0], 8.112, patch.position[1]];
    const entity = patch.region === "greenwood"
      ? addRapidRegionShape("greenwood", `town-threshold:${patch.id}`, "cylinder", material, scale, position)
      : addTownShape(rapidPrototypeRoot, `town-atmosphere:${patch.id}`, "cylinder", material, scale, position);
    entity.setLocalEulerAngles(0, patch.yaw, 0);
  }
  for (const bank of TOWN_GATE_EMBANKMENTS) {
    const mound = addRapidRegionShape("greenwood", `town-threshold:${bank.id}`, "cylinder", greenwoodMoss,
      [bank.width, bank.height, bank.depth], [bank.x, 8.02 + bank.height * .5, bank.z]);
    mound.setLocalEulerAngles(0, bank.yaw, 0);
  }

  // Founder Well water and a subtle rune ring give the civic square a focal
  // point even when the imported well model is viewed from a high camera.
  addTownShape(rapidPrototypeRoot, "founder-well-rune", "cylinder", townRune, [2.45, .022, 2.45], [67, 8.145, 106]);
  addTownShape(rapidPrototypeRoot, "founder-well-water", "cylinder", townWaterMaterial, [1.72, .03, 1.72], [67, 8.19, 106]);
  const thresholdStone = addRapidRegionBox("greenwood", "east-road-milestone", townStoneLight,
    [.52, 1.2, .4], [110.2, 8.64, 99.7]);
  thresholdStone.setLocalEulerAngles(-4, 9, 5);
  addRapidRegionBox("greenwood", "east-road-milestone-rune", townRune,
    [.08, .34, .19], [110.55, 8.75, 99.7]).setLocalEulerAngles(0, 0, 45);

  for (const particle of TOWN_ATMOSPHERE_PARTICLES) {
    const streamed = particle.kind === "leaf" && particle.x >= 108;
    const parent = streamed ? rapidRegionChunkRoot("greenwood", particle.x, particle.z) : rapidPrototypeRoot;
    const entity = addTownShape(parent, `town-atmosphere:${particle.kind}`, particle.kind === "leaf" ? "box" : "sphere",
      particle.kind === "leaf" ? townLeafMaterial : townPollenMaterial,
      particle.kind === "leaf" ? [.12, .035, .25] : [.045, .045, .045], [particle.x, particle.y, particle.z]);
    rapidTownAtmosphere.push({ entity, ...particle });
  }

  // Town of Beginnings terrain: a circular civic square, a readable street
  // hierarchy and planted verges replace the old town-sized rectangle of stone.
  const townTerrainMaterials: Record<TownTerrainMaterial, pc.StandardMaterial> = {
    "road-edge": roadEdge,
    road: roadWarm,
    "plaza-edge": plazaEdge,
    plaza: plazaStone,
    forecourt,
    garden: gardenSoil,
  };
  for (const patch of SPEED_LAB_TOWN_TERRAIN) {
    const scale: [number, number, number] = [...patch.scale];
    const position: [number, number, number] = [...patch.position];
    const entity = patch.shape === "box"
      ? addBox(rapidPrototypeRoot, `town-terrain:${patch.id}`, townTerrainMaterials[patch.material], scale, position)
      : addTownShape(rapidPrototypeRoot, `town-terrain:${patch.id}`, "cylinder", townTerrainMaterials[patch.material], scale, position);
    if (patch.yaw) entity.setLocalEulerAngles(0, patch.yaw, 0);
  }
  for (const item of SPEED_LAB_TOWN_TERRAIN_DETAILS) {
    const [x, y, z] = item.position;
    if (item.kind === "edge-stone") {
      const stone = addBox(rapidPrototypeRoot, `town-terrain:${item.id}`, item.id.length % 2 ? townStone : townStoneLight,
        [item.scale, .045, item.scale * .58], [x, y, z]);
      stone.setLocalEulerAngles(0, item.yaw, (item.id.length % 3 - 1) * 2);
      continue;
    }
    const flowerMaterial = item.kind === "flower-red" ? flowerRed
      : item.kind === "flower-yellow" ? flowerYellow : item.kind === "flower-blue" ? townRune : grassLight;
    for (const offset of [-.12, .12]) {
      const blade = addTownShape(rapidPrototypeRoot, `town-terrain:${item.id}-blade`, "cone", grassLight,
        [.07 * item.scale, .3 * item.scale, .07 * item.scale], [x + offset, y + .12 * item.scale, z - offset * .45]);
      blade.setLocalEulerAngles(offset * 45, item.yaw, offset * 55);
    }
    if (item.kind !== "grass") {
      addTownShape(rapidPrototypeRoot, `town-terrain:${item.id}-bloom`, "sphere", flowerMaterial,
        [.13 * item.scale, .09 * item.scale, .13 * item.scale], [x, y + .33 * item.scale, z]);
    }
  }

  const addGabledRoof = (parent: pc.Entity, name: string, x: number, z: number, width: number, depth: number,
    baseY: number, roof: pc.StandardMaterial, highlight: pc.StandardMaterial, angle = 34): void => {
    const halfSpan = width / 2 + .48;
    const radians = angle * Math.PI / 180;
    const slopeLength = halfSpan / Math.cos(radians);
    const rise = halfSpan * Math.tan(radians);
    for (const side of [-1, 1] as const) {
      const panel = addBox(parent, `${name}-roof-slope`, roof, [slopeLength, .2, depth + .9],
        [x + side * halfSpan / 2, baseY + rise / 2, z]);
      panel.setLocalEulerAngles(0, 0, side < 0 ? angle : -angle);
      for (const band of [.38, .72]) {
        const bandX = x + side * halfSpan * band;
        const bandY = baseY + (halfSpan - Math.abs(bandX - x)) * Math.tan(radians) + .06;
        addBox(parent, `${name}-roof-rib`, highlight, [.075, .075, depth + .96], [bandX, bandY, z]);
      }
    }
    addBox(parent, `${name}-roof-ridge`, highlight, [.24, .24, depth + 1.08], [x, baseY + rise + .02, z]);
  };

  const addTownBuilding = (name: string, x: number, z: number, width: number, depth: number,
    wall: pc.StandardMaterial, roof: pc.StandardMaterial, roofHighlight: pc.StandardMaterial, height = 2.5): pc.Entity => {
    const root = new pc.Entity(name);
    rapidPrototypeRoot.addChild(root);
    addBox(root, `${name}-foundation-shadow`, mortar, [width + .7, .22, depth + .7], [x, 8.12, z]);
    addBox(root, `${name}-foundation`, townStone, [width + .45, .32, depth + .45], [x, 8.22, z]);
    addBox(root, `${name}-walls`, wall, [width, height, depth], [x, 8.28 + height / 2, z]);
    addBox(root, `${name}-lower-timber`, timber, [width + .08, .18, depth + .08], [x, 8.5, z]);
    addBox(root, `${name}-upper-timber`, timber, [width + .08, .18, depth + .08], [x, 8.3 + height * .78, z]);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      addBox(root, `${name}-corner-post`, timber, [.2, height + .15, .2],
        [x + sx * (width / 2 - .11), 8.3 + height / 2, z + sz * (depth / 2 - .11)]);
    }
    for (const side of [-1, 1]) {
      const windowZ = z + side * depth * .26;
      addBox(root, `${name}-window-frame`, timber, [.08, .88, .92], [x + width / 2 + .035, 9.22, windowZ]);
      addBox(root, `${name}-window`, windowGlow, [.085, .68, .72], [x + width / 2 + .075, 9.22, windowZ]);
      addBox(root, `${name}-window-cross`, timber, [.1, .09, .78], [x + width / 2 + .13, 9.22, windowZ]);
      addBox(root, `${name}-window-cross`, timber, [.1, .74, .075], [x + width / 2 + .13, 9.22, windowZ]);
    }
    addBox(root, `${name}-door-frame`, townStone, [.15, 1.72, 1.18], [x + width / 2 + .04, 9.13, z]);
    addBox(root, `${name}-door`, timberLight, [.18, 1.48, .92], [x + width / 2 + .13, 9.02, z]);
    addBox(root, `${name}-door-step`, townStoneLight, [.62, .15, 1.3], [x + width / 2 + .38, 8.27, z]);
    // Decorative gable braces make the eastern gameplay-facing façade read at camera distance.
    for (const side of [-1, 1] as const) {
      const brace = addBox(root, `${name}-gable-brace`, timber, [.12, .12, depth * .43],
        [x + width / 2 + .1, 10.03, z + side * depth * .2]);
      brace.setLocalEulerAngles(side * 32, 0, 0);
    }
    addGabledRoof(root, name, x, z, width, depth, 8.42 + height, roof, roofHighlight);
    return root;
  };

  const hall = addTownBuilding("founders-hall", 91.6, 106, 5.4, 6.2, plasterLight, roofBlue, roofBlueLight, 2.9);
  addBox(hall, "founders-bell-tower-base", timber, [2.02, .2, 2.02], [91.6, 11.78, 106]);
  addBox(hall, "founders-bell-tower", plaster, [1.72, 1.9, 1.72], [91.6, 12.67, 106]);
  for (const side of [-1, 1]) {
    addBox(hall, "founders-belfry-opening", iron, [.42, .76, .08], [91.6 + side * .46, 12.72, 106.89]);
    addBox(hall, "founders-belfry-opening", iron, [.08, .76, .42], [92.48, 12.72, 106 + side * .46]);
  }
  addGabledRoof(hall, "founders-tower", 91.6, 106, 2, 2, 13.62, roofBlue, roofBlueLight, 42);
  addTownShape(hall, "founders-sun-mark", "cylinder", bannerGold, [.48, .08, .48], [92.5, 12.72, 106])
    .setLocalEulerAngles(0, 0, 90);

  const inn = addTownBuilding("wayfarer-inn", 92.2, 96.2, 6.1, 5.2, warmPlaster, roofRed, roofRedLight);
  addBox(inn, "inn-sign-arm", timber, [.12, .12, 1.25], [95.42, 10.18, 97.25]);
  addBox(inn, "inn-sign-board", timberLight, [.14, .84, 1.02], [95.48, 9.72, 97.83]);
  addTownShape(inn, "inn-sign-mug", "cylinder", bannerGold, [.28, .12, .28], [95.57, 9.75, 97.83])
    .setLocalEulerAngles(0, 0, 90);

  const smithy = addTownBuilding("beginnings-smithy", 92.2, 115.8, 6.1, 5.2, warmPlaster, roofRed, roofRedLight);
  addBox(smithy, "smithy-chimney", townStone, [.74, 2.2, .74], [90.2, 11.65, 114.5]);
  addBox(smithy, "smithy-chimney-cap", townStoneLight, [.94, .18, .94], [90.2, 12.79, 114.5]);
  addBox(smithy, "smithy-forge-glow", windowGlow, [.08, .74, 1.25], [95.3, 8.98, 114.55]);
  addBox(smithy, "smith-sign-arm", timber, [.12, .12, 1.2], [95.42, 10.18, 114.55]);
  addBox(smithy, "smith-sign-board", timberLight, [.14, .84, 1.02], [95.48, 9.72, 113.98]);
  const smithHammerHead = addBox(smithy, "smith-sign-hammer", iron, [.11, .18, .6], [95.57, 9.83, 113.98]);
  smithHammerHead.setLocalEulerAngles(35, 0, 0);
  const smithHammerGrip = addBox(smithy, "smith-sign-hammer", bannerGold, [.11, .58, .11], [95.58, 9.55, 113.98]);
  smithHammerGrip.setLocalEulerAngles(-32, 0, 0);
  for (let index = 0; index < 5; index++) {
    const puff = addTownShape(rapidPrototypeRoot, "smithy-smoke", "sphere", smokeMaterial, [.2, .2, .2], [73.3, 13.1, 135.3]);
    rapidTownSmoke.push({ entity: puff, x: 73.3, y: 13.1, z: 135.3, phase: index / 5, drift: -.6 });
  }
  const sparkMaterial = new pc.StandardMaterial();
  sparkMaterial.diffuse = new pc.Color(1, .42, .06);
  sparkMaterial.emissive = new pc.Color(1, .18, .01);
  sparkMaterial.useLighting = false;
  sparkMaterial.update();
  for (let index = 0; index < 6; index++) {
    const spark = addTownShape(rapidPrototypeRoot, "smithy-spark", "sphere", sparkMaterial,
      [.055, .055, .055], [79, 8.85, 136.5]);
    rapidTownSparks.push({ entity: spark, phase: index / 6 });
  }

  const weavers = addTownBuilding("weavers-row", 82, 95, 5.7, 5.2, plaster, roofBlue, roofBlueLight, 2.45);
  addBox(weavers, "weavers-awning", bannerBlue, [.12, .7, 1.7], [84.94, 9.2, 95]);
  for (const offset of [-.48, 0, .48]) addTownShape(weavers, "weavers-cloth", "cylinder",
    offset === 0 ? bannerGold : bannerBlue, [.18, .42, .18], [85.04, 8.65, 95 + offset]);

  const healer = addTownBuilding("healers-house", 82, 106, 5.5, 5.4, plasterLight, roofRed, roofRedLight, 2.55);
  const healerSign = addBox(healer, "healer-sign", townRune, [.09, .82, .82], [84.86, 9.55, 106]);
  healerSign.setLocalEulerAngles(0, 0, 45);
  addBox(healer, "healer-sign-cross", bannerGold, [.1, .16, .68], [84.97, 9.55, 106]);
  addBox(healer, "healer-sign-cross", bannerGold, [.1, .68, .16], [84.98, 9.55, 106]);

  const lodge = addTownBuilding("wardens-lodge", 82, 117, 5.7, 5.2, warmPlaster, roofBlue, roofBlueLight, 2.5);
  addBox(lodge, "lodge-banner", bannerBlue, [.1, 1.5, .75], [84.96, 9.7, 117]);
  addTownShape(lodge, "lodge-sigil", "cylinder", bannerGold, [.25, .08, .25], [85.04, 9.78, 117])
    .setLocalEulerAngles(0, 0, 90);

  const addGatehouse = (z: number): void => {
    addBox(rapidPrototypeRoot, "town-gate-footing", mortar, [2.95, .24, 3.65], [102.1, 8.14, z]);
    addBox(rapidPrototypeRoot, "town-gate-tower", townStone, [2.65, 3.25, 3.35], [102.1, 9.72, z]);
    addBox(rapidPrototypeRoot, "town-gate-face", townStoneMid, [.2, 2.65, 2.65], [103.48, 9.72, z]);
    for (const offset of [-1.12, -.38, .38, 1.12])
      addBox(rapidPrototypeRoot, "town-gate-masonry", townStoneLight, [.12, .12, .48], [103.6, 9.02 + Math.abs(offset) * .56, z + offset]);
    addGabledRoof(rapidPrototypeRoot, "town-gate", 102.1, z, 3, 3.8, 11.36, roofBlue, roofBlueLight, 38);
    const banner = addBox(rapidPrototypeRoot, "town-gate-banner", bannerBlue, [.07, 1.52, .84], [103.54, 10.15, z]);
    rapidTownBanners.push({ entity: banner, phase: z * .41 });
    addBox(rapidPrototypeRoot, "town-gate-banner-tail", bannerBlue, [.075, .42, .55], [103.55, 9.24, z]);
    addTownShape(rapidPrototypeRoot, "town-gate-sigil", "cylinder", bannerGold, [.25, .08, .25], [103.62, 10.25, z])
      .setLocalEulerAngles(0, 0, 90);
  };
  addGatehouse(100.65);
  addGatehouse(111.35);
  // A stepped stone arch leaves a tall, readable opening instead of the old giant brown beam.
  addBox(rapidPrototypeRoot, "town-gate-arch-crown", townStone, [1.32, .6, 9.05], [102.1, 11.18, 106]);
  for (const side of [-1, 1] as const) {
    addBox(rapidPrototypeRoot, "town-gate-arch-step", townStone, [1.34, .58, 1.18], [102.1, 10.72, 106 + side * 3.05]);
    addBox(rapidPrototypeRoot, "town-gate-arch-step", townStoneMid, [1.35, .52, .95], [102.1, 10.38, 106 + side * 2.45]);
  }
  addBox(rapidPrototypeRoot, "town-gate-nameplate", timberLight, [.08, .62, 2.6], [102.82, 11.28, 106]);
  addBox(rapidPrototypeRoot, "town-gate-nameplate-inlay", bannerGold, [.09, .1, 1.82], [102.88, 11.28, 106]);

  const addMarketStall = (name: string, z: number, canopy: pc.StandardMaterial): void => {
    const root = new pc.Entity(name); rapidPrototypeRoot.addChild(root);
    addBox(root, `${name}-rug`, bannerGold, [2.45, .025, 1.42], [98.15, 8.17, z]);
    addBox(root, `${name}-counter`, timberLight, [2.1, .58, .75], [98.15, 8.5, z]);
    for (const side of [-1, 1]) addBox(root, `${name}-post`, timber, [.12, 1.85, .12], [98.15 + side * .87, 9.15, z]);
    const canopyLeft = addBox(root, `${name}-canopy`, canopy, [1.2, .16, 1.62], [97.58, 9.96, z]);
    canopyLeft.setLocalEulerAngles(0, 0, 8);
    const canopyRight = addBox(root, `${name}-canopy`, canopy === bannerBlue ? roofBlueLight : roofRedLight,
      [1.2, .16, 1.62], [98.72, 9.96, z]);
    canopyRight.setLocalEulerAngles(0, 0, -8);
    for (const offset of [-.56, 0, .56]) addTownShape(root, `${name}-wares`, "sphere",
      offset === 0 ? flowerYellow : flowerRed, [.18, .18, .18], [98.15 + offset, 8.9, z - .16]);
  };
  addMarketStall("north-market-stall", 98.2, bannerBlue);
  addMarketStall("south-market-stall", 113.8, roofRed);

  for (const [x, z] of [[96.4,102.8],[96.4,109.2],[100,103.1],[100,108.9]] as const) {
    addTownShape(rapidPrototypeRoot, "town-lamp-post", "cylinder", iron, [.14, 1.72, .14], [x, 8.88, z]);
    addBox(rapidPrototypeRoot, "town-lamp-arm", iron, [.62, .1, .1], [x + .24, 9.58, z]);
    addBox(rapidPrototypeRoot, "town-lamp", windowGlow, [.34, .44, .34], [x + .5, 9.42, z]);
    addTownShape(rapidPrototypeRoot, "town-lamp-cap", "cone", iron, [.5, .35, .5], [x + .5, 9.75, z]);
  }
  for (const [x, z, sx, sz] of [[97.2,93.1,3.2,.55],[97.2,118.9,3.2,.55],[99.9,96.1,.55,2.6],[99.9,115.9,.55,2.6]] as const) {
    addBox(rapidPrototypeRoot, "town-hedge", hedge, [sx, .72, sz], [x, 8.38, z]);
    for (const offset of [-.34, .34]) addTownShape(rapidPrototypeRoot, "town-flower", "sphere",
      offset < 0 ? flowerRed : flowerYellow, [.16, .16, .16], [x + (sx > sz ? offset : 0), 8.78, z + (sz > sx ? offset : 0)]);
  }

  // The Founder Compass is a low, walkable landmark: cyan points east toward adventure.
  addTownShape(rapidPrototypeRoot, "founder-compass-ring", "cylinder", mortar, [1.82, .045, 1.82], [94.6, 8.18, 106]);
  const compassCore = addBox(rapidPrototypeRoot, "founder-compass-core", townRune, [1.9, .035, .42], [94.6, 8.235, 106]);
  compassCore.setLocalEulerAngles(0, 45, 0);
  const compassCross = addBox(rapidPrototypeRoot, "founder-compass-cross", townRune, [.42, .04, 1.9], [94.6, 8.24, 106]);
  compassCross.setLocalEulerAngles(0, 45, 0);

  const addBarrel = (x: number, z: number): void => {
    addTownShape(rapidPrototypeRoot, "town-barrel", "cylinder", timberLight, [.48, .7, .48], [x, 8.48, z]);
    for (const y of [8.2, 8.48, 8.76]) addTownShape(rapidPrototypeRoot, "barrel-hoop", "cylinder", iron, [.5, .045, .5], [x, y, z]);
  };
  addBarrel(95.25, 94.15); addBarrel(95.35, 117.35);
  for (const [x, z, turn] of [[96.4,94.1,8],[97.05,94.35,-12],[96.35,117.7,-8],[97.02,117.45,11]] as const) {
    const crate = addBox(rapidPrototypeRoot, "town-crate", timberLight, [.58, .58, .58], [x, 8.47, z]);
    crate.setLocalEulerAngles(0, turn, 0);
    addBox(rapidPrototypeRoot, "crate-band", timber, [.64, .1, .64], [x, 8.47, z]).setLocalEulerAngles(0, turn, 0);
  }
  for (const [x, z, turn] of [[96.7,99.85,0],[96.7,112.15,0]] as const) {
    addBox(rapidPrototypeRoot, "town-bench-seat", timberLight, [1.8, .16, .48], [x, 8.48, z]).setLocalEulerAngles(0, turn, 0);
    for (const side of [-1, 1]) addBox(rapidPrototypeRoot, "town-bench-leg", iron, [.16, .42, .16], [x + side * .62, 8.28, z]);
  }

  for (const [x, z] of [[76.8,87.5],[84.5,87.5],[91,93],[96,93],[102,93],[108,88],[116,87],[126,88],[133,92],[133,120],[126,124],[116,125],[104,124],[96,120],[86,124],[77,122],[76.5,106],[77,90]] as const) {
    addTownShape(rapidPrototypeRoot, "tree-trunk", "cylinder", trunk, [.42, 1.65, .42], [x, 8.82, z]);
    addTownShape(rapidPrototypeRoot, "tree-crown", "sphere", leaf, [2.1, 1.45, 2.1], [x, 10.05, z]);
    addTownShape(rapidPrototypeRoot, "tree-crown", "sphere", leafLight, [1.38, 1.05, 1.38], [x - .45, 10.72, z - .25]);
    addTownShape(rapidPrototypeRoot, "tree-crown", "sphere", leaf, [1.15, .88, 1.15], [x + .5, 10.62, z + .35]);
  }
  for (const [x, z, s] of [[104,96,1.2],[123,97,.9],[124,114,1.1],[108,116,.8],[98,112,.75]] as const) {
    const rock = addBox(rapidPrototypeRoot, "arena-rock", stone, [s, s * .72, s], [x, 8 + s * .36, z]);
    rock.setLocalEulerAngles(0, x * 7 % 45, 12);
  }

  // Four readable free-roam biomes continue the original game's regional journey.
  // Their shapes are deliberately low-poly and batched so the Fast World keeps its pace.
  for (const [x, z, size] of [[113,83,1.7],[119,127,1.9],[125,86,1.6],[132,130,1.8],[139,83,2],[147,88,1.7],
    [151,126,1.8],[117,114,1.5],[143,116,1.65],[130,96,1.45],[151,98,1.5],[123,103,1.35]] as const) {
    addRapidRegionShape("greenwood", "greenwood-tree-trunk", "cylinder", trunk, [.34 * size, 1.25 * size, .34 * size], [x, 8.62 + size * .42, z]);
    addRapidRegionShape("greenwood", "greenwood-tree-crown", "cone", greenwoodCanopy, [1.25 * size, 2 * size, 1.25 * size], [x, 10 + size * .72, z]);
  }
  for (const [x, z, turn] of [[121,94,18],[132,119,-26],[144,97,32],[147,122,-12],[126,111,8]] as const) {
    const root = addRapidRegionBox("greenwood", "greenwood-root", greenwoodBark, [2.6, .22, .3], [x, 8.24, z]);
    root.setLocalEulerAngles(0, turn, 8);
  }
  for (const log of GREENWOOD_FALLEN_LOGS) {
    const trunk = addRapidRegionShape("greenwood", "greenwood-fallen-log", "cylinder", greenwoodBark,
      [.52, log.length * .5, .52], [log.x, 8.48, log.z]);
    trunk.setLocalEulerAngles(90, log.yaw, 0);
    for (const side of [-1, 1] as const) {
      const cut = addRapidRegionShape("greenwood", "greenwood-log-cut", "cylinder", timberLight,
        [.42, .035, .42], [log.x + Math.sin(log.yaw * Math.PI / 180) * log.length * .48 * side,
          8.48, log.z + Math.cos(log.yaw * Math.PI / 180) * log.length * .48 * side]);
      cut.setLocalEulerAngles(90, log.yaw, 0);
    }
  }
  for (let index = 0; index < GREENWOOD_UNDERGROWTH.length; index++) {
    const [x, z, size] = GREENWOOD_UNDERGROWTH[index]!;
    for (let blade = 0; blade < 3; blade++) {
      const fern = addRapidRegionShape("greenwood", "greenwood-fern", "cone", blade === 1 ? greenwoodFernLight : greenwoodFern,
        [.2 * size, .72 * size, .12 * size], [x + (blade - 1) * .18 * size, 8.34 + blade * .025, z]);
      fern.setLocalEulerAngles(blade === 1 ? -12 : 12, index * 47 + blade * 58, (blade - 1) * 24);
    }
  }
  for (const landmark of GREENWOOD_LANDMARKS) {
    const [x, z] = landmark.position;
    if (landmark.kind === "ruined-camp") {
      // A collapsed expedition camp rewards the first short detour north.
      for (let index = 0; index < 7; index++) {
        const angle = index / 7 * Math.PI * 2;
        const fireStone = addRapidRegionBox("greenwood", `${landmark.id}:fire-stone`, greenwoodStone,
          [.34, .18, .27], [x + Math.cos(angle) * .76, 8.24, z + Math.sin(angle) * .76]);
        fireStone.setLocalEulerAngles(index % 2 ? 8 : -6, -angle * 180 / Math.PI, 4);
      }
      addRapidRegionShape("greenwood", `${landmark.id}:embers`, "cylinder", greenwoodEmber,
        [.5, .035, .5], [x, 8.23, z]);
      addRapidRegionShape("greenwood", `${landmark.id}:flame`, "cone", greenwoodEmber,
        [.22, .6, .22], [x, 8.56, z]);
      for (const side of [-1, 1] as const) {
        const canvas = addRapidRegionBox("greenwood", `${landmark.id}:fallen-tent`, side < 0 ? bannerBlue : roofBlueLight,
          [2.2, .1, 2.35], [x - 2.5 + side * .55, 8.95, z - 1.5]);
        canvas.setLocalEulerAngles(0, landmark.yaw, side * 42);
      }
      for (const offset of [-1, 1] as const) {
        const seat = addRapidRegionBox("greenwood", `${landmark.id}:log-seat`, greenwoodBark,
          [2.2, .3, .34], [x + .15, 8.36, z + offset * 1.65]);
        seat.setLocalEulerAngles(0, landmark.yaw + offset * 7, 0);
      }
      const brokenStandard = addRapidRegionBox("greenwood", `${landmark.id}:broken-standard`, timber,
        [.18, 2.25, .18], [x + 2.55, 9.14, z - .9]);
      brokenStandard.setLocalEulerAngles(0, landmark.yaw, -18);
      addRapidRegionBox("greenwood", `${landmark.id}:torn-banner`, bannerBlue,
        [.08, .72, .68], [x + 2.82, 9.62, z - .9]).setLocalEulerAngles(0, landmark.yaw, -11);
      continue;
    }
    if (landmark.kind === "ancient-shrine") {
      // Low concentric steps and asymmetrical stones create a readable sacred
      // silhouette without introducing a collision wall across the route.
      addRapidRegionShape("greenwood", `${landmark.id}:lower-step`, "cylinder", greenwoodStone,
        [3.4, .14, 3.4], [x, 8.2, z]);
      addRapidRegionShape("greenwood", `${landmark.id}:moss-step`, "cylinder", greenwoodMoss,
        [2.55, .12, 2.55], [x, 8.36, z]);
      const altar = addRapidRegionBox("greenwood", `${landmark.id}:altar`, townStoneLight,
        [1.65, .72, 1.1], [x, 8.78, z]);
      altar.setLocalEulerAngles(0, landmark.yaw, 0);
      addRapidRegionShape("greenwood", `${landmark.id}:rune`, "cylinder", townRune,
        [.58, .045, .58], [x, 9.17, z]).setLocalEulerAngles(0, landmark.yaw, 0);
      for (let index = 0; index < 5; index++) {
        const angle = index / 5 * Math.PI * 2 + .35;
        const pillar = addRapidRegionBox("greenwood", `${landmark.id}:root-stone`, greenwoodStone,
          [.48, 1.25 + index % 2 * .38, .42], [x + Math.cos(angle) * 3.15,
            8.75 + index % 2 * .18, z + Math.sin(angle) * 3.15]);
        pillar.setLocalEulerAngles(index % 2 ? 5 : -7, -angle * 180 / Math.PI, index % 2 ? -5 : 8);
      }
      continue;
    }
    if (landmark.kind === "corrupted-grove") {
      // Corruption appears as veins and growths, not a clean circular arena.
      for (let index = 0; index < 7; index++) {
        const angle = index / 7 * Math.PI * 2 + .2;
        const reach = 1.2 + index % 3 * .85;
        const vein = addRapidRegionBox("greenwood", `${landmark.id}:blight-vein`, greenwoodCorruption,
          [reach, .055, .16 + index % 2 * .08], [x + Math.cos(angle) * reach * .48,
            8.18 + index * .001, z + Math.sin(angle) * reach * .48]);
        vein.setLocalEulerAngles(0, -angle * 180 / Math.PI, index % 2 ? 3 : -3);
        const bulbX = x + Math.cos(angle) * (reach + .35);
        const bulbZ = z + Math.sin(angle) * (reach + .35);
        addRapidRegionShape("greenwood", `${landmark.id}:blight-bulb`, "sphere", greenwoodCorruption,
          [.3 + index % 2 * .1, .4 + index % 3 * .08, .3 + index % 2 * .1], [bulbX, 8.48, bulbZ]);
      }
      for (const side of [-1, 1] as const) {
        const snag = addRapidRegionShape("greenwood", `${landmark.id}:snag`, "cylinder", greenwoodBark,
          [.33, 1.75, .33], [x + side * 2.7, 9.05, z + side * .9]);
        snag.setLocalEulerAngles(side * 10, landmark.yaw + side * 18, side * 14);
      }
      continue;
    }
    if (landmark.kind === "guarded-cache") {
      // The guards own the real drops. The abandoned cache makes their
      // optional reward detour readable without adding another HUD objective.
      const cache = addRapidRegionBox("greenwood", `${landmark.id}:cache`, timberLight,
        [1.55, .72, 1.05], [x, 8.58, z]);
      cache.setLocalEulerAngles(0, landmark.yaw, 0);
      addRapidRegionBox("greenwood", `${landmark.id}:cache-lid`, timber,
        [1.68, .22, 1.16], [x, 9, z]).setLocalEulerAngles(0, landmark.yaw, 0);
      for (const side of [-1, 1] as const)
        addRapidRegionBox("greenwood", `${landmark.id}:cache-band`, iron,
          [.12, .82, 1.12], [x + side * .48, 8.65, z]).setLocalEulerAngles(0, landmark.yaw, 0);
      for (const [dx, dz, yaw] of [[-1.6, .7, 14], [1.45, .85, -22], [.9, -1.2, 31]] as const) {
        const supply = addRapidRegionBox("greenwood", `${landmark.id}:supply`, timberLight,
          [.72, .58, .72], [x + dx, 8.43, z + dz]);
        supply.setLocalEulerAngles(0, landmark.yaw + yaw, 0);
      }
      const post = addRapidRegionBox("greenwood", `${landmark.id}:fenward-sign-post`, greenwoodBark,
        [.15, 1.8, .15], [x + 3.2, 9, z - 2]);
      post.setLocalEulerAngles(0, -35, -3);
      addRapidRegionBox("greenwood", `${landmark.id}:fenward-sign`, timberLight,
        [.18, .55, 1.55], [x + 3.2, 9.78, z - 2]).setLocalEulerAngles(0, -35, 0);
      continue;
    }
    // The leader grove gets a thorn arch that reads from the main path. It
    // frames the fight but leaves the combat centre and retreat lane clear.
    for (const side of [-1, 1] as const) {
      const archRoot = addRapidRegionShape("greenwood", `${landmark.id}:arch-root`, "cylinder", greenwoodBark,
        [.48, 2.25, .48], [x - 6.4, 9.75, z + side * 3.15]);
      archRoot.setLocalEulerAngles(side * 8, side * 9, side * 7);
    }
    const archCrown = addRapidRegionBox("greenwood", `${landmark.id}:arch-crown`, greenwoodBark,
      [.52, .48, 6.8], [x - 6.4, 11.52, z]);
    archCrown.setLocalEulerAngles(0, 0, -4);
    for (const side of [-1, 1] as const)
      addRapidRegionShape("greenwood", `${landmark.id}:thorn-crown`, "cone", greenwoodCorruption,
        [.34, .72, .34], [x - 6.05, 11.5, z + side * 2.35]).setLocalEulerAngles(0, 0, 90);
  }
  for (const standingStone of GREENWOOD_GROVE_STONES) {
    const stoneRoot = addRapidRegionBox("greenwood", "elderthorn-standing-stone", greenwoodStone,
      [.48, 1.3, .38], [standingStone.x, 8.7, standingStone.z]);
    stoneRoot.setLocalEulerAngles(standingStone.yaw * .12, standingStone.yaw, standingStone.yaw > 0 ? 7 : -7);
    addRapidRegionShape("greenwood", "elderthorn-stone-moss", "sphere", greenwoodMoss,
      [.44, .16, .34], [standingStone.x, 9.6, standingStone.z]);
  }
  // A natural clearing replaces the old bright boss pad. The centre remains open
  // for readable combat while roots, stones and motes frame the Elderthorn Keeper.
  for (let index = 0; index < 10; index++) {
    const angle = index / 10 * Math.PI * 2;
    const root = addRapidRegionBox("greenwood", "elderthorn-crown-root", greenwoodBark, [2.2, .17, .24],
      [150.5 + Math.cos(angle) * 5.45, 8.25, 106.5 + Math.sin(angle) * 5.45]);
    root.setLocalEulerAngles(0, 90 - angle * 180 / Math.PI, index % 2 ? 7 : -5);
  }
  for (let index = 0; index < 12; index++) {
    const angle = index / 12 * Math.PI * 2;
    const moteX = 150.5 + Math.cos(angle) * (3.4 + index % 3);
    const moteZ = 106.5 + Math.sin(angle) * (3.4 + index % 3);
    const entity = addTownShape(rapidRegionChunkRoot("greenwood", moteX, moteZ), "elderthorn-firefly", "sphere", greenwoodMoteMaterial,
      [.075, .075, .075], [moteX, 8.8 + index % 4 * .35, moteZ]);
    rapidGreenwoodMotes.push({ entity, x: entity.getLocalPosition().x, y: entity.getLocalPosition().y,
      z: entity.getLocalPosition().z, phase: index * .73 });
  }

  for (const pool of MISTFEN_TOXIC_POOLS) {
    const water = addRapidRegionShape("mistfen", `mistfen-pool:${pool.id}`, "cylinder", mistfenWater,
      [pool.width, .035, pool.depth], [pool.x, 8.075, pool.z]);
    water.setLocalEulerAngles(0, pool.yaw, 0);
    const rim = addRapidRegionShape("mistfen", `mistfen-pool-rim:${pool.id}`, "cylinder", marshGlow,
      [pool.width + .22, .018, pool.depth + .22], [pool.x, 8.068, pool.z]);
    rim.setLocalEulerAngles(0, pool.yaw, 0);
  }
  for (const walk of MISTFEN_BOARDWALKS) {
    const deck = addRapidRegionBox("mistfen", `mistfen-boardwalk:${walk.id}`, timberLight,
      [walk.length, .12, walk.width], [walk.x, 8.2, walk.z]);
    deck.setLocalEulerAngles(0, walk.yaw, 0);
    const angle = walk.yaw * Math.PI / 180;
    for (const side of [-1, 1] as const) for (const end of [-1, 1] as const) {
      const along = walk.length * .42 * end;
      const across = walk.width * .47 * side;
      const stakeX = walk.x + Math.cos(angle) * along - Math.sin(angle) * across;
      const stakeZ = walk.z - Math.sin(angle) * along - Math.cos(angle) * across;
      addRapidRegionBox("mistfen", `mistfen-boardwalk-stake:${walk.id}`, timber,
        [.14, .7, .14], [stakeX, 8.52, stakeZ]).setLocalEulerAngles(0, walk.yaw, side * 4);
    }
  }
  for (const snagDefinition of MISTFEN_SNAGS) {
    const snag = addRapidRegionBox("mistfen", "mistfen-snag", timber, [.3, 2.1, .3],
      [snagDefinition.x, 9.05, snagDefinition.z]);
    snag.setLocalEulerAngles(0, snagDefinition.yaw, snagDefinition.yaw * .35);
    const branch = addRapidRegionBox("mistfen", "mistfen-snag-branch", timberLight, [1.2, .18, .18],
      [snagDefinition.x + .35, 9.95, snagDefinition.z]);
    branch.setLocalEulerAngles(0, snagDefinition.yaw, -18);
  }
  for (let index = 0; index < MISTFEN_REEDS.length; index++) {
    const [x, z] = MISTFEN_REEDS[index]!;
    for (let blade = 0; blade < 3; blade++) {
      const reed = addRapidRegionShape("mistfen", "mistfen-reed", "cone", blade === 1 ? marshGlow : greenwoodFern,
        [.16, .85 + blade * .13, .13], [x + (blade - 1) * .22, 8.48, z]);
      reed.setLocalEulerAngles((blade - 1) * 7, index * 41 + blade * 36, (blade - 1) * 14);
    }
  }
  for (const landmark of MISTFEN_LANDMARKS) {
    if (landmark.kind === "drowned-camp") {
      const platform = addRapidRegionBox("mistfen", `${landmark.id}:platform`, timber,
        [4.8, .16, 3.5], [landmark.x, 8.24, landmark.z]);
      platform.setLocalEulerAngles(0, -18, -3);
      for (const side of [-1, 1] as const)
        addRapidRegionBox("mistfen", `${landmark.id}:broken-pole`, timberLight,
          [.16, 1.65 + side * .2, .16], [landmark.x + side * 1.6, 9.05, landmark.z - .9])
          .setLocalEulerAngles(side * 8, -18, side * 12);
    } else if (landmark.kind === "reed-maze") {
      for (let index = 0; index < 12; index++) {
        const angle = index / 12 * Math.PI * 2;
        const radius = index % 2 ? 3.6 : 2.6;
        addRapidRegionShape("mistfen", `${landmark.id}:high-reed`, "cone", greenwoodFern,
          [.3, 1.65, .22], [landmark.x + Math.cos(angle) * radius, 8.82,
            landmark.z + Math.sin(angle) * radius]).setLocalEulerAngles(0, index * 37, index % 2 ? 8 : -8);
      }
    } else if (landmark.kind === "corrupted-spring") {
      addRapidRegionShape("mistfen", `${landmark.id}:spring`, "cylinder", mistfenWater,
        [3.1, .045, 3.1], [landmark.x, 8.1, landmark.z]);
      for (let index = 0; index < 8; index++) {
        const angle = index / 8 * Math.PI * 2;
        addRapidRegionShape("mistfen", `${landmark.id}:bubble`, "sphere", marshGlow,
          [.18 + index % 2 * .08, .12, .18 + index % 2 * .08],
          [landmark.x + Math.cos(angle) * 2.3, 8.22, landmark.z + Math.sin(angle) * 2.3]);
      }
    } else if (landmark.kind === "guarded-cache") {
      const cache = addRapidRegionBox("mistfen", `${landmark.id}:cache`, timberLight,
        [1.55, .72, 1.05], [landmark.x, 8.58, landmark.z]);
      cache.setLocalEulerAngles(0, 18, 0);
      addRapidRegionBox("mistfen", `${landmark.id}:lid`, timber,
        [1.68, .22, 1.16], [landmark.x, 9, landmark.z]).setLocalEulerAngles(0, 18, 0);
      for (const side of [-1, 1] as const)
        addRapidRegionBox("mistfen", `${landmark.id}:band`, iron,
          [.12, .82, 1.12], [landmark.x + side * .48, 8.65, landmark.z]).setLocalEulerAngles(0, 18, 0);
    } else {
      // A raised, irregular mud island preserves readable footing while toxic
      // water and roots create the Miremother's pressure lanes.
      addRapidRegionShape("mistfen", `${landmark.id}:island`, "cylinder", mistfenMud,
        [6.2, .18, 5.5], [landmark.x, 8.16, landmark.z]);
      for (let index = 0; index < 9; index++) {
        const angle = index / 9 * Math.PI * 2;
        const root = addRapidRegionBox("mistfen", `${landmark.id}:root`, timber,
          [1.8, .15, .22], [landmark.x + Math.cos(angle) * 4.7, 8.32,
            landmark.z + Math.sin(angle) * 4.15]);
        root.setLocalEulerAngles(0, 90 - angle * 180 / Math.PI, index % 2 ? 6 : -5);
      }
    }
  }
  for (const [x, y, z, sx, sz] of [[160,9.2,54,5,2.4],[174,9.5,33,6,2.7],[190,9.15,62,5.5,2.3],
    [200,9.55,35,4.5,2.2],[181,9.3,72,5,2.2]] as const)
    addRapidRegionShape("mistfen", "mistfen-ground-fog", "sphere", mistfenFog, [sx, .55, sz], [x, y, z]);
  for (const [x, z, range, intensity] of [[179.5,51.5,10,1.05],[197,54.5,7,.8],[186.5,36,6,.65]] as const) {
    const light = new pc.Entity("mistfen-marsh-light");
    light.addComponent("light", { type: "omni", color: new pc.Color(.34, .7, .45), intensity,
      range, castShadows: false });
    light.setLocalPosition(x, 9.2, z);
    rapidRegionChunkRoot("mistfen", x, z).addChild(light);
  }

  for (const pool of SUNKEN_COAST_TIDE_POOLS) {
    const water = addRapidRegionShape("sunken-coast", "coast-tide-pool", "cylinder", coastWater,
      [pool.width, .035, pool.depth], [pool.x, 8.075, pool.z]);
    water.setLocalEulerAngles(0, pool.yaw, 0);
    const foam = addRapidRegionShape("sunken-coast", "coast-tide-foam", "cylinder", coastFoam,
      [pool.width + .24, .018, pool.depth + .24], [pool.x, 8.068, pool.z]);
    foam.setLocalEulerAngles(0, pool.yaw, 0);
  }
  for (const wreck of SUNKEN_COAST_WRECKAGE) {
    const beam = addRapidRegionBox("sunken-coast", "coast-wreck-beam", timberLight,
      [wreck.length, .28, .36], [wreck.x, 8.28, wreck.z]);
    beam.setLocalEulerAngles(0, wreck.yaw, wreck.yaw > 0 ? 7 : -7);
    for (const side of [-1, 1]) {
      const rib = addRapidRegionBox("sunken-coast", "coast-wreck-rib", timber,
        [.25, .85, 1.25], [wreck.x + side * 1.15, 8.55, wreck.z]);
      rib.setLocalEulerAngles(0, wreck.yaw + side * 12, side * 24);
    }
  }
  for (const [x, z, size] of SUNKEN_COAST_ROCKS) {
    const rock = addRapidRegionBox("sunken-coast", "coast-rock", greenwoodStone,
      [size, size * .65, size * .82], [x, 8 + size * .34, z]);
    rock.setLocalEulerAngles(8, x * 13 % 55, z % 2 ? 7 : -8);
  }
  for (const [x, z] of SUNKEN_COAST_GRASS) {
    for (let blade = 0; blade < 3; blade++) {
      const grassBlade = addRapidRegionShape("sunken-coast", "coast-grass", "cone", coastGrass,
        [.16, .68 + blade * .08, .11], [x + (blade - 1) * .22, 8.35, z]);
      grassBlade.setLocalEulerAngles(blade === 1 ? -8 : 10, x * 9 + blade * 47, (blade - 1) * 20);
    }
  }
  addRapidRegionShape("sunken-coast", "tidecaller-ring", "cylinder", coastWater,
    [5.8, .055, 5.8], [70.5, 8.11, 174.5]);

  for (const [x, z, sx, sz, height] of [[158,142,9,5,.5],[188,141,12,4,.75],[155,181,8,5,.65],[184,184,13,4,1.05],
    [199,154,5,9,.8],[171,165,7,6,.55]] as const)
    addRapidRegionBox("southern-quarry", "quarry-terrace", quarryRock, [sx, height, sz], [x, 8 + height * .5, z]);
  for (const [x, z, size] of [[161,153,1.3],[174,144,.9],[193,159,1.5],[199,181,1.2],[168,181,1],[188,174,1.35]] as const) {
    const rock = addRapidRegionBox("southern-quarry", "quarry-boulder", quarryRock, [size, size * .8, size], [x, 8 + size * .4, z]);
    rock.setLocalEulerAngles(10, x * 11 % 46, 8);
    addRapidRegionShape("southern-quarry", "quarry-ore", "sphere", ironOre, [.3 * size, .22 * size, .18 * size], [x + .45 * size, 8 + size * .7, z]);
  }
  addRapidRegionShape("southern-quarry", "quarrymaster-ring", "cylinder", ironOre, [5.6, .06, 5.6], [198.5, 8.12, 166.5]);

  for (const [x, z, length, turn] of [[210,82,6,22],[222,94,8,-14],[239,78,7,31],[248,96,6,-24],[214,132,7,-10],
    [232,119,9,18],[250,132,6,9]] as const) {
    const crack = addRapidRegionBox("ashen-reach", "ashen-lava-rift", lava, [length, .045, .32], [x, 8.075, z]);
    crack.setLocalEulerAngles(0, turn, 0);
  }
  for (const [x, z, height] of [[211,91,2.4],[220,78,3.2],[237,134,2.8],[251,84,3.5],[253,122,2.6],[225,129,2.2]] as const) {
    const spire = addRapidRegionShape("ashen-reach", "ashen-spire", "cone", ashRock, [1.2, height, 1.2], [x, 8 + height * .5, z]);
    spire.setLocalEulerAngles(0, x * 9 % 50, z % 2 ? 8 : -8);
  }
  addRapidRegionShape("ashen-reach", "cinderlord-ring", "cylinder", lava, [6.2, .065, 6.2], [242.5, 8.13, 106.5]);

  for (const [x, z, material] of [[108,106,greenwoodCanopy],[168,82,mistfenWater],[168,136,ironOre],[204,106,lava]] as const) {
    addRapidWorldBox("region-threshold-left", stone, [.48, 2.2, .48], [x, 9.1, z - 3.5]);
    addRapidWorldBox("region-threshold-right", stone, [.48, 2.2, .48], [x, 9.1, z + 3.5]);
    addRapidWorldShape("region-threshold-flame", "sphere", material, [.42, .42, .42], [x, 11.3, z - 3.5]);
    addRapidWorldShape("region-threshold-flame", "sphere", material, [.42, .42, .42], [x, 11.3, z + 3.5]);
  }
  for (const x of [96.5, 103.5]) {
    addRapidWorldBox("coast-threshold", stone, [.48, 2.2, .48], [x, 9.1, 148]);
    addRapidWorldShape("coast-threshold-flame", "sphere", coastWater, [.42, .42, .42], [x, 11.3, 148]);
  }
  for (const sign of FAST_WORLD_SIGNPOSTS) {
    const parentRegion = sign.regionId === "town" ? null : sign.regionId;
    const post = parentRegion
      ? addRapidRegionBox(parentRegion, `route-sign:${sign.id}:post`, timber, [.16, 1.75, .16], [sign.x, 8.9, sign.z])
      : addRapidWorldBox(`route-sign:${sign.id}:post`, timber, [.16, 1.75, .16], [sign.x, 8.9, sign.z]);
    post.setLocalEulerAngles(0, 18, -3);
    const board = parentRegion
      ? addRapidRegionBox(parentRegion, `route-sign:${sign.id}:board`, timberLight, [.18, .58, 1.7], [sign.x, 9.65, sign.z])
      : addRapidWorldBox(`route-sign:${sign.id}:board`, timberLight, [.18, .58, 1.7], [sign.x, 9.65, sign.z]);
    board.setLocalEulerAngles(0, 18, 0);
    const cap = parentRegion
      ? addRapidRegionShape(parentRegion, `route-sign:${sign.id}:marker`, "sphere", townRune, [.18, .18, .18], [sign.x, 9.66, sign.z])
      : addRapidWorldShape(`route-sign:${sign.id}:marker`, "sphere", townRune, [.18, .18, .18], [sign.x, 9.66, sign.z]);
    cap.setLocalPosition(sign.x + .2, 9.66, sign.z);
  }

  // The imported kit is decorative only: server-owned world geometry remains authoritative for
  // movement and combat. Primitive art stays visible until a complete replacement family loads.
  const hideRapidTownFallback = (family: TownFallbackFamily): void => {
    const names = family === "complete-buildings" ? new Set(["founders-hall", "wayfarer-inn", "beginnings-smithy",
      "weavers-row", "healers-house", "wardens-lodge"])
      : family === "market-stalls" ? new Set(["north-market-stall", "south-market-stall"])
      : family === "street-props" ? new Set(["town-barrel", "barrel-hoop", "town-crate", "crate-band",
        "town-bench-seat", "town-bench-leg"])
      : family === "lamp-posts" ? new Set(["town-lamp-post", "town-lamp-arm", "town-lamp", "town-lamp-cap"])
      : family === "trees" ? new Set(["tree-trunk", "tree-crown"])
      : new Set(["arena-rock"]);
    for (const node of rapidPrototypeRoot.find(graphNode => names.has(graphNode.name))) node.enabled = false;
  };
  let townAssetsStarted = false;
  requestRapidTownAssets = () => {
    if (townAssetsStarted) return;
    townAssetsStarted = true;
    void populateTownAssetKit(app, rapidPrototypeRoot, SPEED_LAB_TOWN_ASSETS).then(result => {
      for (const family of readyTownFallbacks(result.loadedIds)) hideRapidTownFallback(family);
      console.info(`[town-assets] ${result.entities.length} placements ready; ${result.failedIds.size} model types kept their fallback.`);
    });
  };
  let greenwoodAssetsStarted = false;
  requestGreenwoodAssets = () => {
    if (greenwoodAssetsStarted) return;
    greenwoodAssetsStarted = true;
    void populateTownAssetKit(app, rapidPrototypeRoot, GREENWOOD_ASSET_PLACEMENTS, "greenwood-asset").then(result => {
      for (const entity of result.entities) {
        const position = entity.getLocalPosition().clone();
        const rotation = entity.getLocalRotation().clone();
        const scale = entity.getLocalScale().clone();
        entity.reparent(rapidRegionChunkRoot("greenwood", position.x, position.z));
        entity.setLocalPosition(position);
        entity.setLocalRotation(rotation);
        entity.setLocalScale(scale);
        for (const node of entity.find(candidate => Boolean((candidate as pc.Entity).render))) {
          const render = (node as pc.Entity).render;
          if (render) render.batchGroupId = rapidWorldSceneryBatchGroup.id;
        }
      }
      const treesReady = result.loadedIds.has("treeCrooked") && result.loadedIds.has("treeHighRound");
      if (treesReady) for (const node of rapidPrototypeRoot.find(candidate =>
        candidate.name === "greenwood-tree-trunk" || candidate.name === "greenwood-tree-crown")) node.enabled = false;
      console.info(`[greenwood-assets] ${result.entities.length} nature placements ready; ` +
        `${result.failedIds.size} model types retained their procedural fallback.`);
    });
  };

  addRapidWorldBox("north-edge", boundary, [220, .5, .65], [150, 8.25, 20.3]);
  addRapidWorldBox("south-edge", boundary, [220, .5, .65], [150, 8.25, 191.7]);
