type InventoryDecision = "equipped" | "upgrade" | "different" | "lower" | "same";
function decisionFromTrends(trends: ReturnType<typeof comparisonTrend>[]): InventoryDecision {
  const better = trends.filter(trend => trend === "better").length;
  const worse = trends.filter(trend => trend === "worse").length;
  if (better === 0 && worse === 0) return "same";
  if (better > 0 && worse === 0) return "upgrade";
  if (worse > 0 && better === 0) return "lower";
  return "different";
}
function inventoryDecisionForItem(itemId: ItemId): InventoryDecision | null {
  const hand = equipmentForItem(itemId);
  if (hand) {
    if (hand === localMainHandId) return "equipped";
    const selected = weaponComparison(hand, localIronSwordOwned, equipmentRank(itemId));
    const worn = weaponComparison(localMainHandId, localIronSwordOwned, equipmentRank(itemForMainHand(localMainHandId)));
    return decisionFromTrends([
      comparisonTrend(selected.damageValue, worn.damageValue), comparisonTrend(selected.rangeValue, worn.rangeValue),
      comparisonTrend(selected.speedValue, worn.speedValue, true),
    ]);
  }
  const armour = armourForItem(itemId);
  if (!armour) return null;
  if (armour === localArmourId) return "equipped";
  const selected = armourComparison(armour, equipmentRank(itemId));
  const worn = armourComparison(localArmourId, equipmentRank(localArmourId === "none" ? null : localArmourId));
  return decisionFromTrends([
    comparisonTrend(selected.reductionValue, worn.reductionValue), comparisonTrend(selected.speedValue, worn.speedValue),
    comparisonTrend(selected.rangedValue, worn.rangedValue), comparisonTrend(selected.hazardValue, worn.hazardValue),
  ]);
}
const inventoryDecisionLabel: Record<InventoryDecision, string> = {
  equipped: "EQUIPPED", upgrade: "CLEAR UPGRADE", different: "TRADE-OFF", lower: "LOWER STATS", same: "SAME STATS",
};

function refreshInventorySelectionActions(): void {
  const itemId = selectedInventoryItem;
  const hand = itemId ? equipmentForItem(itemId) : null;
  const armour = itemId ? armourForItem(itemId) : null;
  const owned = itemId ? (inventoryCounts.get(itemId) ?? 0) > 0 : false;
  inventoryDecisionPanel.hidden = !itemId || !owned || (!hand && !armour);
  inventorySelectionActions.hidden = !itemId || !owned || (!hand && !armour);
  if (inventorySelectionActions.hidden) return;
  const equipped = hand ? hand === localMainHandId : armour === localArmourId;
  const canUnequip = Boolean(armour && armour === localArmourId);
  const firstVictoryChoice = firstVictoryReward?.stage === "choose" && itemId === firstVictoryReward.itemId;
  inventorySelectedEquip.disabled = equipped && !canUnequip;
  inventorySelectedEquip.textContent = canUnequip ? "UNEQUIP" : equipped ? "EQUIPPED"
    : firstVictoryChoice ? "EQUIP UPGRADE" : "EQUIP NOW";
  inventorySelectedKeep.textContent = firstVictoryChoice ? "KEEP FOR LATER" : "CLEAR";
  const recipe = Object.hasOwn(BLACKSMITH_DISMANTLE, itemId!)
    ? BLACKSMITH_DISMANTLE[itemId! as BlacksmithDismantleItemId] : null;
  inventorySelectedDismantle.hidden = !recipe;
  inventorySelectedDismantle.disabled = !recipe || (equipped && (inventoryCounts.get(itemId!) ?? 0) <= 1);
  inventorySelectedDismantle.textContent = recipe
    ? `${inventorySelectedDismantle.disabled ? "EQUIPPED · " : ""}DISMANTLE AT SMITH · +${recipe.gold} GOLD`
    : "DISMANTLE AT SMITH";
}

function refreshInventoryPreview(): void {
  if (inventoryPanel.hidden) return;
  const previewOpen = document.querySelector<HTMLDetailsElement>("#inventory-preview-drawer")!.open;
  if (previewOpen && !inventoryPortrait) {
    inventoryPortrait = createLazyCharacterPortrait(document.querySelector<HTMLCanvasElement>("#inventory-portrait")!, localPlayerRig.root,
      (hand, armour) => {
        setRigMainHand(localPlayerRig, hand);
        setRigArmour(localPlayerRig, armour);
        return () => {
          setRigMainHand(localPlayerRig, localMainHandId);
          setRigArmour(localPlayerRig, localArmourId);
        };
      });
  }
  const hand = previewHand ?? localMainHandId;
  const armour = previewArmour ?? localArmourId;
  const appearanceKey = `${hand}:${armour}:${localAppearance.skin}:${localAppearance.hair}:${localAppearance.coat}:${localAppearance.hairStyle}:${localAppearance.coatStyle}`;
  const comparisonKey = `${appearanceKey}:${localMainHandId}:${localArmourId}:${localIronSwordOwned}:${previewSlot}:${selectedInventoryItem ?? "worn"}:${JSON.stringify(blacksmithReforgeRanks)}`;
  for (const card of inventoryPanel.querySelectorAll<HTMLElement>("article.equipment[data-item]"))
    card.dataset.selected = String(card.dataset.item === selectedInventoryItem);
  if (previewOpen) inventoryPortrait!.refresh(hand, armour, appearanceKey);
  if (comparisonKey === inventoryComparisonKey) return;
  inventoryComparisonKey = comparisonKey;
  if (!selectedInventoryItem) {
    inventoryDecisionPanel.hidden = true;
    inventorySelectionActions.hidden = true;
    return;
  }
  const worn = document.querySelector<HTMLElement>("#inventory-worn-stats")!;
  const selected = document.querySelector<HTMLElement>("#inventory-selected-stats")!;
  if (previewSlot === "armour") {
    fillArmourComparison(worn, localArmourId); fillArmourComparison(selected, armour, equipmentRank(selectedInventoryItem ?? (armour === "none" ? null : armour)), localArmourId);
  } else {
    fillLootComparison(worn, localMainHandId); fillLootComparison(selected, hand, equipmentRank(selectedInventoryItem ?? itemForMainHand(hand)), localMainHandId);
  }
  refreshInventorySelectionActions();
  const decision = inventoryDecisionForItem(selectedInventoryItem) ?? "different";
  inventoryDecisionName.textContent = ITEM_DEFINITIONS[selectedInventoryItem].name;
  inventoryDecisionVerdict.textContent = inventoryDecisionLabel[decision];
  inventoryDecisionPanel.dataset.verdict = decision;
  const roll = equipmentAffixes[selectedInventoryItem];
  if (firstVictoryReward?.stage === "choose" && selectedInventoryItem === firstVictoryReward.itemId)
    inventoryCallingFit.textContent = firstVictoryCallingFit(localBuildPathId, ITEM_DEFINITIONS[selectedInventoryItem].name);
  else if (!localBuildPathId) inventoryCallingFit.textContent = "No combat style chosen yet. This item still works normally.";
  else if (!roll) inventoryCallingFit.textContent = `Works normally with your ${BUILD_PATHS[localBuildPathId].name} style.`;
  else {
    const itemPath = EQUIPMENT_AFFIXES[roll.affixId].pathId;
    inventoryCallingFit.textContent = itemPath === localBuildPathId
      ? `✓ Great for your ${BUILD_PATHS[itemPath].name} style.`
      : `Built for ${BUILD_PATHS[itemPath].name}, not your current ${BUILD_PATHS[localBuildPathId].name} style.`;
  }
  const changed = hand !== localMainHandId || armour !== localArmourId;
  document.querySelector<HTMLElement>("#inventory-preview-label")!.textContent = changed ? "Preview only · not equipped" : "Currently equipped";
}

function updatePowerLoadout(powerId: PowerId): void {
  localPrimaryPower = powerId;
  if (activePowerSlot === "primary") activatePowerSlot("primary", false);
  else combatHud.setPowerLoadout(localPrimaryPower, localSecondaryPower, activePowerSlot, localCharacterProgression.level);
}

function updateSecondaryPowerLoadout(powerId: PowerId): void {
  localSecondaryPower = powerId;
  if (activePowerSlot === "secondary") activatePowerSlot("secondary", false);
  else combatHud.setPowerLoadout(localPrimaryPower, localSecondaryPower, activePowerSlot, localCharacterProgression.level);
}

function activatePowerSlot(slot: "primary" | "secondary", announce = true): boolean {
  if (!WEAPON_TECHNIQUES_AVAILABLE) return false;
  if (slot === "secondary" && localCharacterProgression.level < 5) {
    if (announce) status.textContent = "Weapon techniques unlock at character level 5.";
    return false;
  }
  activePowerSlot = slot;
  localEquippedPower = slot === "primary" ? localPrimaryPower : localSecondaryPower;
  combatHud.setPowerLoadout(localPrimaryPower, localSecondaryPower, activePowerSlot, localCharacterProgression.level);
  updateControlsHelp();
  refreshPowerCompatibility();
  return true;
}

function updateSeismicMastery(masteryId: SeismicMasteryId): void {
  localSeismicMastery = masteryId;
  combatHud.setSeismicMastery(masteryId);
}

function requestSeismicMastery(masteryId: SeismicMasteryId): void {
  if (!room || !worldReady || masteryId === localSeismicMastery) return;
  if (powerAimActive || localPowerStartedAt !== null) {
    status.textContent = "Finish or cancel Seismic Cleave before changing its mastery.";
    return;
  }
  seismicMasterySequence += 1;
  room.send("power:seismic-mastery", {
    requestId: `seismic-mastery-${seismicMasterySequence}`,
    masteryId,
  });
  status.textContent = `Equipping ${SEISMIC_CLEAVE_UPGRADES.masteries[masteryId].name}...`;
}

function updateControlsHelp(): void {
  const power = POWER_DEFINITIONS[localEquippedPower];
  const powerHint = power.castType === "tap" ? `R ${power.name}` : `Hold R ${power.core === "ground" ? "place" : "aim"} ${power.name}`;
  const fireHint = WEAPON_ATTACK_DEFINITIONS[localMainHandId].projectileTravelMs > 0 ? " · Hold J or left-click to fire · Mouse aim optional" : "";
  const secondaryHint = localCharacterProgression.level >= 5 ? ` · T ${POWER_DEFINITIONS[localSecondaryPower].name}` : "";
  const calling = CALLING_ABILITY_OPTIONS.find(option => option.id === localCallingAbilityId);
  const callingSpecial = CALLING_ABILITY_OPTIONS.find(option => option.pathId === localBuildPathId && option.category === "Utility");
  const callingHint = localCharacterProgression.level >= 2 && calling ? ` · G ${calling.name}` : "";
  const unlockedPowerHint = WEAPON_TECHNIQUES_AVAILABLE && localCharacterProgression.level >= 5 ? ` · ${powerHint}${secondaryHint}` : "";
  const unlockedSpecialHint = localCharacterProgression.level >= 4 && callingSpecial
    ? ` · F ${callingSpecial.name}` : "";
  controlsHelp.textContent = `WASD move · Arrows camera · J main-hand attack · I inventory · H potion · Hold C/right-click Guard · Space dodge/cancel${unlockedPowerHint}${unlockedSpecialHint}${callingHint} · Q mode · E/click acts${fireHint}`;
}

function updateTouchAbilityVisibility(): void {
  const callingUnlocked = localCharacterProgression.level >= 2 && Boolean(localBuildPathId && localCallingAbilityId);
  const specialUnlocked = localCharacterProgression.level >= 4 && Boolean(localBuildPathId);
  callingButton.hidden = !callingUnlocked;
  callingButton.disabled = !callingUnlocked;
  specialButton.hidden = !specialUnlocked;
  specialButton.disabled = !specialUnlocked;
  powerButton.hidden = !WEAPON_TECHNIQUES_AVAILABLE || localCharacterProgression.level < 5;
}

function updateSpecialLoadout(specialId: SpecialId): void {
  localFieldSpecialSelected = false;
  localEquippedSpecial = specialId;
  combatHud.setSpecial(specialId);
  combatHud.setFieldSpecialSelected(false);
  specialButton.textContent = localCharacterProgression.level < 4 ? "LV 4" : "Special";
  updateControlsHelp();
}

function requestCallingAbility(slot: "power" | "special" = "power", aimedYaw?: number): void {
  if (reportedProtectedDialog === true) return;
  if (!room || !worldReady) return;
  if (localCharacterProgression.level < (slot === "special" ? 4 : 2)) return;
  if (!localBuildPathId) {
    status.textContent = "Choose a Calling in Town to unlock this ability slot.";
    showCombatFeedback("CALLING UNBOUND", "hurt");
    return;
  }
  const now = Date.now();
  if (now < (slot === "special" ? localCallingSpecialCooldownUntil : localCallingCooldownUntil)) {
    const definition = slot === "special" ? CALLING_ABILITY_OPTIONS.find(option => option.pathId === localBuildPathId && option.category === "Utility")
      : CALLING_ABILITY_OPTIONS.find(option => option.id === localCallingAbilityId);
    showCombatFeedback(`${definition?.name.toUpperCase() ?? "CALLING"} RECHARGING`, "hurt");
    return;
  }
  if (performance.now() < callingAbilityPendingUntil) return;
  callingAbilityPendingUntil = performance.now() + 700;
  callingAbilitySequence += 1;
  if (slot === "power") combatHud.setCallingPending(true);
  createCallingAnticipation(localBuildPathId);
  firstPersonAbilityCastStartedAt = performance.now();
  firstPersonAbilityCastDuration = slot === "special" ? 900 : 700;
  const pendingSequence = callingAbilitySequence;
  window.setTimeout(() => {
    if (callingAbilitySequence === pendingSequence && performance.now() >= callingAbilityPendingUntil) {
      combatHud.setCallingPending(false);
    }
  }, 720);
  const requestId = `calling-${callingAbilitySequence}`;
  combatSync.start("calling", requestId, performance.now());
  const training = slot === "power" && guidedAbilityPracticeId === localCallingAbilityId
    && guidedAbilityPracticePhase === "cast" && localPlayer.getPosition().distance(CALLING_EFFIGY_POSITION) <= 4;
  room.send("calling:ability", { requestId, yaw: aimedYaw ?? cameraOrbit.yaw, slot, ...(training ? { training: true } : {}) });
}

function requestSpecialEquip(specialId: SpecialId): void {
  if (!FIELD_TECHNIQUES_AVAILABLE) return;
  if (!room || !worldReady) return;
  if (localCharacterProgression.level < 5) return;
  if (specialId === localEquippedSpecial) {
    localFieldSpecialSelected = true;
    combatHud.setFieldSpecialSelected(true);
    updateControlsHelp();
    return;
  }
  if (specialAimActive || localPowerStartedAt !== null || localActionStartedAt !== null) {
    status.textContent = "Finish or cancel the current action before changing Special.";
    return;
  }
  specialEquipSequence += 1;
  fieldSpecialSelectionBeforeEquip = localFieldSpecialSelected;
  room.send("special:equip", { requestId: `special-equip-${specialEquipSequence}`, specialId });
  localFieldSpecialSelected = true;
  combatHud.setFieldSpecialSelected(true);
  updateControlsHelp();
  status.textContent = `Equipping ${SPECIAL_DEFINITIONS[specialId].name}...`;
}

function updateMainHandLoadout(mainHandId: MainHandId): void {
  localMainHandId = mainHandId;
  setFirstPersonMainHand(mainHandId);
  localComboStep = 0;
  localComboExpiresAt = 0;
  targetStateKey = "";
  refreshPowerCompatibility();
  refreshBackpackCapacity();
  if (mainHandId === "forged_sword" && (firstStepsIndex === ONBOARDING_STAGE.equipSword || forcedStarterEquipment)) {
    completeStarterEquipment();
    if (firstStepsIndex === ONBOARDING_STAGE.equipSword) noteFirstStep("equipped_starter");
    showCombatFeedback("FORGED SWORD EQUIPPED", "dodge");
    status.textContent = "Forged Sword equipped · your first loadout is ready.";
    if (!inventoryPanel.hidden) setInventoryOpen(false);
  }
  if (firstVictoryReward?.stage === "choose" && isItemId(firstVictoryReward.itemId)
    && equipmentForItem(firstVictoryReward.itemId) === mainHandId)
    completeFirstVictoryDecision("equipped");
}

function requestPowerEquip(powerId: PowerId): void {
  if (!WEAPON_TECHNIQUES_AVAILABLE) return;
  if (!room || !worldReady || powerId === localEquippedPower) return;
  if (localCharacterProgression.level < 5) return;
  if (powerAimActive || localPowerStartedAt !== null) {
    status.textContent = "Finish or cancel the current Power before changing it.";
    return;
  }
  if (!isPowerCompatibleWithMainHand(POWER_DEFINITIONS[powerId], localMainHandId)) {
    const mainHand = MAIN_HAND_DEFINITIONS[localMainHandId];
    status.textContent = `${POWER_DEFINITIONS[powerId].name} is not compatible with ${mainHand.name}.`;
    showCombatFeedback("INCOMPATIBLE POWER", "hurt");
    return;
  }
  powerEquipSequence += 1;
  room.send("power:equip", { requestId: `power-equip-${powerEquipSequence}`, powerId, slot: activePowerSlot });
  status.textContent = `Equipping ${POWER_DEFINITIONS[powerId].name} to the ${activePowerSlot} slot...`;
}

function requestMainHandEquip(mainHandId: MainHandId): void {
  if (!room || !worldReady || mainHandId === localMainHandId) return;
  if (powerAimActive || localPowerStartedAt !== null) {
    status.textContent = "Finish or cancel the current Power before changing main hand.";
    return;
  }
  mainHandEquipSequence += 1;
  room.send("main-hand:equip", { requestId: `main-hand-equip-${mainHandEquipSequence}`, mainHandId });
  status.textContent = `Equipping ${MAIN_HAND_DEFINITIONS[mainHandId].name}...`;
}

function updateTraitLoadout(traitId: TraitId): void {
  localTraitId = traitId;
  const definition = TRAIT_DEFINITIONS[traitId];
  traitName.textContent = definition.name;
  traitDetail.textContent = definition.description;
  traitSlot.dataset.trait = traitId;
  momentumPips[0]?.parentElement?.toggleAttribute("hidden", traitId !== "momentum");
  traitBonus.hidden = traitId === "momentum";
  traitBonus.textContent = traitId === "bulwark" ? "−35% GUARD" : traitId === "executioner" ? "+1 VULNERABLE" : "";
  for (const button of traitPickerButtons) button.setAttribute("aria-pressed", String(button.dataset.trait === traitId));
  if (traitId !== "momentum") updateMomentum(0);
  else updateMomentum(localMomentumStacks);
}

function requestTraitEquip(traitId: TraitId): void {
  if (!room || !worldReady || traitId === localTraitId) return;
  if (powerAimActive || specialAimActive || localPowerStartedAt !== null || localActionStartedAt !== null || localDefending) {
    status.textContent = "Finish the current combat action before changing Trait.";
    return;
  }
  traitEquipSequence += 1;
  room.send("trait:equip", { requestId: `trait-equip-${traitEquipSequence}`, traitId });
  status.textContent = `Equipping ${TRAIT_DEFINITIONS[traitId].name}...`;
}

function updatePlayerHealth(health: number, maximumHealth: number): void {
  potionHealth = health;
  potionMaxHealth = maximumHealth;
  playerHud.setHealth(health, maximumHealth);
}

function updatePlayerStamina(stamina: number, maximumStamina: number): void {
  playerHud.setStamina(stamina, maximumStamina);
}

function syncPredictedDodgeStamina(stamina: number, maximumStamina: number): void {
  const now = performance.now();
  localPredictedDodgeStaminaMaximum = maximumStamina;
  if (!localPredictedDodgeStaminaReady) {
    localPredictedDodgeStamina = stamina;
    localPredictedDodgeStaminaReady = true;
  } else {
    const recovered = advancePredictedDodgeStamina(
      localPredictedDodgeStamina,
      predictedDodgeRecoveryElapsed(localPredictedDodgeStaminaAt, now, localDodgeExhaustedUntil),
      maximumStamina,
    );
    // A delayed server patch must never refund stamina already reserved by a
    // newer local dodge prediction.
    localPredictedDodgeStamina = Math.min(stamina, recovered);
  }
  localPredictedDodgeStaminaAt = now;
}

function renderCharacterProgression(update: ProgressionUpdate, maximumHealth = potionMaxHealth): void {
  localCharacterProgression = update;
  if (lastBuildPathUpdate) renderAssassinJourney(lastBuildPathUpdate);
  const required = Math.max(0, update.experienceRequired);
  playerHud.setProgression(update.level, update.experience, required);
  combatHud.setPowerLoadout(localPrimaryPower, localSecondaryPower, activePowerSlot, update.level);
  powerButton.disabled = !WEAPON_TECHNIQUES_AVAILABLE || update.level < 5;
  updateTouchAbilityVisibility();
  updateControlsHelp();
  inventoryLevel.textContent = required > 0 ? `${update.level} · ${update.experience}/${required} XP` : `${update.level} · MAX`;
  characterPoints.textContent = update.unspentStatPoints > 0 ? `${update.unspentStatPoints} POINT${update.unspentStatPoints === 1 ? "" : "S"} AVAILABLE` : "NO POINTS AVAILABLE";
  statPower.textContent = `${update.powerPoints} · +${characterPowerBonus(update.powerPoints)} damage`;
  statVitality.textContent = `${update.vitalityPoints} · ${maximumHealth} max HP`;
  statAgility.textContent = `${update.agilityPoints} · ${Math.round(characterSpeedMultiplier(update.agilityPoints) * 100)}% speed`;
  statMining.textContent = `${update.miningPoints} · ×${1 + characterMiningBonus(update.miningPoints)} yield`;
  characterMilestones.replaceChildren(...CHARACTER_MILESTONES.map(milestone => {
    const row = document.createElement("article");
    const unlocked = update.level >= milestone.level;
    row.dataset.unlocked = String(unlocked);
    row.innerHTML = `<span>${unlocked ? "✓" : `LV ${milestone.level}`}</span><div><strong>${milestone.name}</strong><small>${milestone.detail}</small></div>`;
    return row;
  }));
  activatePowerSlot(activePowerSlot, false);
  levelUpTitle.textContent = `Level ${update.level}!`;
  levelUpMessage.textContent = update.reason === "level_up" ? `You earned ${update.experienceGranted ?? 0} XP from ${update.source ?? "adventuring"}. Spend a permanent stat point below.` : "Spend your permanent stat points below.";
  levelUpPoints.textContent = `${update.unspentStatPoints} point${update.unspentStatPoints === 1 ? "" : "s"} available`;
  playerLevel.dataset.points = String(update.unspentStatPoints > 0);
  refreshStatChoiceButtons();
  updateLevelUpCallingGuide();
  refreshCallingUnlockNotice();
  if (update.unspentStatPoints <= 0) levelUpPanel.hidden = true;
}

function updateLevelUpCallingGuide(): void {
  const active = localBuildPathId ? BUILD_PATHS[localBuildPathId] : null;
  const power = localCallingAbilityId ? CALLING_ABILITY_OPTIONS.find(option => option.id === localCallingAbilityId) : null;
  const special = localBuildPathId ? CALLING_ABILITY_OPTIONS.find(option => option.pathId === localBuildPathId && option.category === "Utility") : null;
  const canChooseCalling = lastBuildPathUpdate?.canChoose === true;
  levelUpCallingNote.textContent = callingLevelGuide(localCharacterProgression.level,
    active ? { name: active.name, power: power?.name ?? "Calling power", special: special?.name ?? "Calling special" } : null,
    canChooseCalling);
  levelUpCallingAction.hidden = Boolean(active) || !canChooseCalling;
}

function updateLevelCelebration(now: number): void {
  if (pendingLevelCelebrations.length && levelCelebration.hidden && worldReady && defeatScreen.hidden
    && reportedProtectedDialog !== true && !localCombatActive()) {
    const celebration = pendingLevelCelebrations.shift()!;
    activeLevelCelebration = celebration;
    levelCelebrationTitle.textContent = `LEVEL ${celebration.level}!`;
    levelCelebrationChoose.hidden = localCharacterProgression.unspentStatPoints <= 0;
    levelCelebration.hidden = false;
    levelCelebrationUntil = now + 5_500;
    combatAudio.play("levelUp");
    levelUpBurst();
  }
  if (!levelCelebration.hidden && activeLevelCelebration) {
    const celebration = activeLevelCelebration;
    const calling = callingUnlockAnnouncement(celebration.level, localBuildPathId);
    const milestone = CHARACTER_MILESTONES.find(entry => entry.level === celebration.level);
    levelCelebrationDetail.textContent = calling
      ? `${calling.title} · ${calling.detail} A permanent stat point is also ready.`
      : milestone ? `${milestone.name} unlocked · a permanent stat point is ready.`
        : `A permanent stat point is ready · +${celebration.experienceGranted} XP.`;
  }
  if (!levelCelebration.hidden && (now >= levelCelebrationUntil || reportedProtectedDialog === true || localCombatActive()))
    { levelCelebration.hidden = true; activeLevelCelebration = null; }
}

function abilityRevealStorageKey(abilityId: CallingAbilityId): string {
  return `calling-ability-reveal-v1:${profileToken}:${abilityId}`;
}

function abilityPracticeStorageKey(abilityId: CallingAbilityId): string {
  return `calling-ability-practice-v1:${profileToken}:${abilityId}`;
}

function unseenCallingAbilityIds(): CallingAbilityId[] {
  const update = lastBuildPathUpdate;
  if (!update?.selectedPathId) return [];
  return earnedCallingAbilities(update.selectedPathId, update.rank, localCharacterProgression.level)
    .filter(id => {
      if (seenAbilityReveals.has(id)) return false;
      try { return window.localStorage.getItem(abilityRevealStorageKey(id)) !== "1"; }
      catch { return true; }
    });
}

function isAtTownOfBeginnings(): boolean {
  if (activeRoomName !== WORLD_ROOM || playerCutaway.active) return false;
  const position = localPlayer.getPosition();
  return Math.hypot(position.x - TOWN_CENTER_X, position.z - TOWN_CENTER_Z) < TOWN_SAFE_RADIUS;
}

function updateAbilityReveal(): void {
  if (!abilityRevealPanel.hidden || !canPresentAbilityReveal({ worldReady, inTown: isAtTownOfBeginnings(),
    defeated: !defeatScreen.hidden, levelCelebrating: !levelCelebration.hidden || pendingLevelCelebrations.length > 0,
    otherDialogOpen: reportedProtectedDialog === true })) return;
  const id = unseenCallingAbilityIds()[0];
  if (!id) return;
  const definition = CALLING_ABILITY_OPTIONS.find(option => option.id === id)!;
  activeAbilityRevealId = id;
  const awakening = callingAwakening(definition.pathId);
  abilityRevealPanel.dataset.calling = definition.pathId;
  abilityRevealPanel.style.setProperty("--calling-colour", awakening.colour);
  abilityRevealPanel.style.setProperty("--calling-accent", awakening.accent);
  abilityRevealPath.textContent = `${BUILD_PATHS[definition.pathId].name.toUpperCase()} · ABILITY UNLOCKED`;
  abilityRevealPreview.innerHTML = callingPreviewMarkup(definition.pathId, `${definition.name} preview`);
  abilityRevealTitle.textContent = definition.name;
  abilityRevealDescription.textContent = definition.description;
  abilityRevealUseHint.textContent = `${abilityRevealUse(id, localBuildPathRank, localCharacterProgression.level)} Town practice is optional.`;
  abilityRevealContinue.textContent = shouldGuideFirstCallingUse(id, localCallingAbilityId, callingPowerUsed(id))
    ? "CONTINUE · PRACTICE OPTIONAL" : "CONTINUE";
  abilityRevealPanel.hidden = false;
  combatAudio.play("levelUp");
  resetMovementControls();
  abilityRevealContinue.focus();
}

abilityRevealContinue.addEventListener("click", () => {
  const id = activeAbilityRevealId;
  if (!id) return;
  social.event(`${CALLING_ABILITY_OPTIONS.find(option => option.id === id)!.name} unlocked.`);
  seenAbilityReveals.add(id);
  try { window.localStorage.setItem(abilityRevealStorageKey(id), "1"); }
  catch { /* Keep the one-session acknowledgement if storage is unavailable. */ }
  if (shouldGuideFirstCallingUse(id, localCallingAbilityId, callingPowerUsed(id))) startGuidedAbilityPractice(id);
  activeAbilityRevealId = null;
  abilityRevealPanel.hidden = true;
  refreshCallingUnlockNotice();
  canvas.focus();
});

function updateAshenEquipmentReveal(): void {
  if (!pendingAshenEquipmentReveal || !ashenEquipmentRevealPanel.hidden || !isAtTownOfBeginnings()
    || localCombatActive() || !defeatScreen.hidden || reportedProtectedDialog === true) return;
  const forged = pendingAshenEquipmentReveal;
  ashenEquipmentRevealTitle.textContent = forged.name;
  ashenEquipmentRevealDescription.textContent = forged.description;
  ashenEquipmentRevealIcon.textContent = forged.blueprint === "cinderfang" ? "⚔" : forged.blueprint === "ashguard" ? "◆" : "✦";
  blacksmithPanel.hidden = true;
  ashenEquipmentRevealPanel.hidden = false;
  combatAudio.play("levelUp"); levelUpBurst(); resetMovementControls();
  ashenEquipmentRevealContinue.focus();
}

ashenEquipmentRevealContinue.addEventListener("click", () => {
  pendingAshenEquipmentReveal = null;
  ashenEquipmentRevealPanel.hidden = true;
  document.querySelector<HTMLButtonElement>("#inventory-toggle")?.click();
});

function callingPowerUsed(abilityId: CallingAbilityId): boolean {
  try { return window.localStorage.getItem(`calling-power-used-v1:${profileToken}:${abilityId}`) === "1"; }
  catch { return false; }
}

function startGuidedAbilityPractice(abilityId: CallingAbilityId): void {
  guidedAbilityPracticeId = abilityId;
  guidedAbilityPracticePhase = "cast";
  guidedAbilityPracticeHits = 0;
  window.clearTimeout(guidedTankImpactTimer);
  dismissedUseAbilityId = null;
  try { window.localStorage.setItem(abilityPracticeStorageKey(abilityId), "1"); }
  catch { /* The current session still keeps the practice active. */ }
  updateGuidedAbilityPractice(performance.now());
}

function dismissGuidedAbilityPractice(): void {
  const abilityId = guidedAbilityPracticeId;
  guidedAbilityPracticeId = null;
  guidedAbilityPracticePhase = "cast";
  guidedAbilityPracticeHits = 0;
  window.clearTimeout(guidedTankImpactTimer);
  if (abilityId) {
    try { window.localStorage.removeItem(abilityPracticeStorageKey(abilityId)); }
    catch { /* Leaving Town still dismisses practice for the current session. */ }
  }
  callingEffigy.enabled = false;
  callingPracticeProjections.forEach(projection => { projection.enabled = false; });
  callingFirstUse.hidden = true;
  callingSlot.dataset.firstUse = "false";
}

function completeGuidedAbilityPractice(abilityId: CallingAbilityId): void {
  if (guidedAbilityPracticeId !== abilityId) return;
  if (localPlayer.getPosition().distance(CALLING_EFFIGY_POSITION) > 4) {
    guidedAbilityPracticePhase = "cast";
    guidedAbilityPracticeHits = 0;
    status.textContent = "Use your new Power beside the glowing Calling Effigy in Town to finish practice.";
    updateGuidedAbilityPractice(performance.now());
    return;
  }
  guidedAbilityPracticeId = null;
  guidedAbilityPracticePhase = "complete";
  guidedAbilityPracticeHits = 0;
  window.clearTimeout(guidedTankImpactTimer);
  try { window.localStorage.removeItem(abilityPracticeStorageKey(abilityId)); }
  catch { /* Completion is still retained by the existing used-Power key. */ }
  callingEffigy.enabled = false;
  callingFirstUse.hidden = true;
  callingSlot.dataset.firstUse = "false";
  showCombatFeedback("POWER MASTERED · EXPLORATION READY", "dodge");
  combatAudio.play("levelUp");
  levelUpBurst();
  status.textContent = "Ability mastered · follow Realm Guidance or explore beyond Town.";
  social.event(`${CALLING_ABILITY_OPTIONS.find(option => option.id === abilityId)?.name ?? "Calling Power"} practiced at the Town effigy.`);
}

function acceptGuidedAbilityPractice(abilityId: CallingAbilityId): void {
  if (guidedAbilityPracticeId !== abilityId || !localBuildPathId) return;
  guidedAbilityPracticePhase = practicePhaseAfterCast(localBuildPathId);
  if (guidedAbilityPracticePhase === "complete") {
    completeGuidedAbilityPractice(abilityId);
    return;
  }
  if (localBuildPathId === "tank") {
    guidedTankImpactTimer = window.setTimeout(() => {
      if (guidedAbilityPracticeId !== abilityId || guidedAbilityPracticePhase !== "follow_up") return;
      createRangedPopup(CALLING_EFFIGY_POSITION.clone().add(new pc.Vec3(0, 2.5, 0)), "BLOCKED", "melee", false, [.35, 1, .76]);
      showCombatFeedback("BULWARK HELD · TEST STRIKE BLOCKED", "dodge");
      completeGuidedAbilityPractice(abilityId);
    }, 1_050);
  }
  updateGuidedAbilityPractice(performance.now());
}

function noteGuidedAbilityPracticeAttack(): void {
  if (!guidedAbilityPracticeId || guidedAbilityPracticePhase !== "follow_up" || !localBuildPathId
    || (localBuildPathId !== "assassin" && localBuildPathId !== "ranger")
    || localPlayer.getPosition().distance(CALLING_EFFIGY_POSITION) > 4) return;
  const progress = practiceFollowUpProgress(localBuildPathId, guidedAbilityPracticeHits);
  guidedAbilityPracticeHits = progress.hits;
  const remaining = abilityPracticeChallenge(localBuildPathId).followUpHits - progress.hits;
  createRangedPopup(CALLING_EFFIGY_POSITION.clone().add(new pc.Vec3(0, 2.3, 0)),
    localBuildPathId === "assassin" ? "EMPOWERED STRIKE" : `FOCUSED SHOT ${progress.hits} / 3`,
    "melee", false, localBuildPathId === "assassin" ? [.72, .45, 1] : [.45, 1, .62]);
  if (progress.complete) completeGuidedAbilityPractice(guidedAbilityPracticeId);
  else {
    status.textContent = `${remaining} empowered shot${remaining === 1 ? "" : "s"} remaining.`;
    updateGuidedAbilityPractice(performance.now());
  }
}

function resumeGuidedAbilityPractice(): void {
  if (guidedAbilityPracticeId || !localCallingAbilityId) return;
  try {
    if (window.localStorage.getItem(abilityPracticeStorageKey(localCallingAbilityId)) === "1")
      guidedAbilityPracticeId = localCallingAbilityId;
  } catch { /* Nothing to resume when storage is unavailable. */ }
}

function updateGuidedAbilityPractice(now: number): void {
  resumeGuidedAbilityPractice();
  if (shouldDismissOptionalPractice(Boolean(guidedAbilityPracticeId), isAtTownOfBeginnings())) {
    dismissGuidedAbilityPractice();
    refreshProgressionNotice();
    return;
  }
  const abilityId = guidedAbilityPracticeId;
  const active = Boolean(abilityId && worldReady && isAtTownOfBeginnings() && defeatScreen.hidden);
  callingEffigy.enabled = active;
  callingFirstUse.hidden = !active;
  callingSlot.dataset.firstUse = String(active);
  if (!active || !abilityId) return;
  const definition = CALLING_ABILITY_OPTIONS.find(option => option.id === abilityId)!;
  const distance = localPlayer.getPosition().distance(CALLING_EFFIGY_POSITION);
  const challenge = abilityPracticeChallenge(definition.pathId);
  const projectionCount = definition.pathId === "mage" || definition.pathId === "thief" || definition.pathId === "ranger" ? 3 : 1;
  for (let index = 0; index < callingPracticeProjections.length; index++) {
    const projection = callingPracticeProjections[index]!;
    projection.enabled = index < projectionCount;
    projection.setLocalEulerAngles(0, now * .035 + index * 120, 0);
    const base = index === 0 ? [-1.7, 0] : index === 1 ? [1.7, 0] : [0, 1.65];
    projection.setLocalPosition(base[0]!, .28 + Math.sin(now * .004 + index) * .08, base[1]!);
  }
  callingFirstUseTitle.textContent = `${definition.name} · optional practice`;
  callingFirstUseDetail.textContent = distance > 4 ? firstCallingUseInstruction(distance)
    : guidedAbilityPracticePhase === "cast" ? challenge.castInstruction : challenge.followUpInstruction;
  callingFirstUseKey.textContent = guidedAbilityPracticePhase === "follow_up"
    && (definition.pathId === "assassin" || definition.pathId === "ranger") ? "J" : "G";
  callingFirstUseAction.textContent = distance > 4 ? "OPTIONAL · APPROACH THE EFFIGY"
    : guidedAbilityPracticePhase === "cast" ? `USE ${definition.name.toUpperCase()}`
      : definition.pathId === "tank" ? "TEST STRIKE INCOMING"
        : definition.pathId === "assassin" ? "J · EMPOWERED STRIKE"
          : `J · FOCUSED SHOT ${guidedAbilityPracticeHits} / ${challenge.followUpHits}`;
  const pulse = 1 + Math.sin(now * .005) * .045;
  callingEffigy.setLocalScale(pulse, pulse, pulse);
  callingEffigy.rotateLocal(0, .18, 0);
}

function refreshProgressionNotice(): void {
  if (guidedAbilityPracticeId) {
    currentProgressionNotice = null;
    updateProgressionNoticeVisibility(performance.now());
    return;
  }
  const selectedAbility = CALLING_ABILITY_OPTIONS.find(option => option.id === localCallingAbilityId);
  const next = chooseProgressionNotice({
    level: localCharacterProgression.level,
    unspentPoints: localCharacterProgression.unspentStatPoints,
    statDismissed: dismissedStatLevel === localCharacterProgression.level,
    hasCalling: Boolean(localBuildPathId), canChooseCalling: lastBuildPathUpdate?.canChoose === true,
    callingDismissed: dismissedCallingLevel === localCharacterProgression.level,
    newAbilityNames: [],
    equipDismissed: dismissedEquipKey === `${lastBuildPathUpdate?.selectedPathId}:${lastBuildPathUpdate?.rank}`,
    equippedAbilityName: isAtTownOfBeginnings() && localCharacterProgression.level >= 2 ? selectedAbility?.name ?? null : null,
    equippedAbilityUsed: !selectedAbility || callingPowerUsed(selectedAbility.id),
    useDismissed: dismissedUseAbilityId === selectedAbility?.id,
  });
  currentProgressionNotice = next;
  updateProgressionNoticeVisibility(performance.now());
}

function updateProgressionNoticeVisibility(now: number): void {
  if ((currentProgressionNotice || activeWorldNotice || pendingWorldNotices.length) && now - progressionNoticeCombatCheckedAt >= 100) {
    progressionNoticeCombatCheckedAt = now;
    progressionNoticeCombatActive = localCombatActive();
  }
  const blocked = !worldReady || !defeatScreen.hidden
    || !levelCelebration.hidden || pendingLevelCelebrations.length > 0
    || !callingFirstUse.hidden
    || reportedProtectedDialog === true || now < progressionNoticeQuietUntil || progressionNoticeCombatActive;
  if (activeWorldNotice && !blocked && worldNoticeLastTick > 0) activeWorldNoticeRemainingMs -= Math.max(0, now - worldNoticeLastTick);
  worldNoticeLastTick = blocked ? 0 : now;
  if (activeWorldNotice && activeWorldNoticeRemainingMs <= 0) activeWorldNotice = null;
  if (!activeWorldNotice && pendingWorldNotices.length && !blocked) {
    activeWorldNotice = pendingWorldNotices.shift()!;
    activeWorldNoticeRemainingMs = activeWorldNotice.durationMs;
  }
  const notice = activeWorldNotice;
  const next = notice ?? currentProgressionNotice;
  const hidden = blocked || !next;
  if (next) {
    const heading = notice?.heading ?? "NEW FOR YOUR CHARACTER";
    if (progressionNoticeHeading.textContent !== heading) progressionNoticeHeading.textContent = heading;
    if (progressionNoticeTitle.textContent !== next.title) progressionNoticeTitle.textContent = next.title;
    if (progressionNoticeDetail.textContent !== next.detail) progressionNoticeDetail.textContent = next.detail;
    progressionNoticePanel.dataset.kind = notice?.kind ?? currentProgressionNotice!.kind;
    if (!notice && currentProgressionNotice && progressionNoticeAction.textContent !== currentProgressionNotice.action)
      progressionNoticeAction.textContent = currentProgressionNotice.action;
  }
  progressionNoticeAction.hidden = Boolean(notice);
  progressionNoticeLater.hidden = Boolean(notice);
  if (progressionNoticePanel.hidden !== hidden) progressionNoticePanel.hidden = hidden;
}

function refreshCallingUnlockNotice(): void {
  combatHud.setNewCallingUnlock(null);
  refreshProgressionNotice();
}

function renderAssassinJourney(update: BuildPathUpdate): void {
  assassinJourneyPanel.hidden = update.selectedPathId !== "assassin";
  if (assassinJourneyPanel.hidden) return;
  const journey = assassinJourney(update, localCharacterProgression.level);
  const activeAbility = update.selectedCallingAbilityId === "assassin_blade_dance" ? "Blade Dance" : "Stealth";
  buildPathMessage.textContent = `G · ${activeAbility} ${localCharacterProgression.level >= 2 ? "ready" : "at character LV 2"}  ·  F · Death Mark ${localCharacterProgression.level >= 4 ? "ready" : "at character LV 4"}. Path Mastery unlocks build choices.`;
  assassinJourneyNext.textContent = `NEXT · ${journey.next}`;
  assassinJourneyTrial.hidden = !journey.trial;
  assassinJourneyTrial.textContent = journey.trial ? `ACTIVE TRIAL · ${journey.trial}` : "";
}

function focusCallingPreview(button: HTMLButtonElement): void {
  for (const candidate of buildPathCandidates.querySelectorAll<HTMLButtonElement>("button"))
    candidate.dataset.previewing = String(candidate === button);
}

function closeCallingAwakening(): void {
  if (callingAwakeningContinue.disabled) return;
  callingAwakeningPanel.hidden = true;
  window.clearTimeout(callingAwakeningTimer);
  beginFirstStepsAfterCalling();
  canvas.focus();
}

function beginCallingAwakening(pathId: BuildPathId, powerName: string): void {
  const definition = BUILD_PATHS[pathId];
  const awakening = callingAwakening(pathId);
  callingIntro.hidden = true;
  callingAwakeningPanel.dataset.calling = pathId;
  callingAwakeningPanel.style.setProperty("--calling-colour", awakening.colour);
  callingAwakeningPanel.style.setProperty("--calling-accent", awakening.accent);
  callingAwakeningPreview.innerHTML = callingPreviewMarkup(pathId, definition.name);
  callingAwakeningTitle.textContent = `${definition.name.toUpperCase()} CALLING AWAKENED`;
  callingAwakeningIdentity.textContent = awakening.identity;
  callingAwakeningPower.textContent = `${powerName} · ${awakening.action}`;
  callingAwakeningUnlock.textContent = localCharacterProgression.level >= 2
    ? "Ready now · Press G to use"
    : "Unlocks at character level 2 · Press G to use";
  callingAwakeningContinue.disabled = true;
  callingAwakeningContinue.textContent = "AWAKENING…";
  callingAwakeningPanel.hidden = false;
  createCallingAnticipation(pathId);
  levelUpBurst();
  combatAudio.play("levelUp");
  resetMovementControls();
  window.clearTimeout(callingAwakeningTimer);
  callingAwakeningTimer = window.setTimeout(() => {
    callingAwakeningContinue.disabled = false;
    callingAwakeningContinue.textContent = "BEGIN THIS PATH";
    callingAwakeningContinue.focus();
  }, CALLING_AWAKENING_MINIMUM_MS);
}

callingAwakeningContinue.addEventListener("click", closeCallingAwakening);

function renderBuildPath(update: BuildPathUpdate): void {
  lastBuildPathUpdate = update;
  if (!callingFirstOnboardingPending
    && shouldStartCallingFirstJourney(firstStepsIndex, localCharacterProgression.level,
      fastWorldRequested && !update.selectedPathId)) {
    callingFirstOnboardingPending = true;
    try { window.localStorage.setItem(callingFirstOnboardingKey, "pending"); } catch { /* Storage may be unavailable. */ }
  }
  renderAssassinJourney(update);
  const previousPathId = localBuildPathId;
  localBuildPathId = update.selectedPathId;
  tutorialCallingId = update.selectedPathId;
  renderFirstSteps();
  localCallingAbilityId = update.selectedCallingAbilityId;
  localCallingAugmentId = update.selectedCallingAugmentId;
  localCallingAugmentProgress = update.callingAugmentProgress;
  localMasteredCallingAugments = update.masteredCallingAugments;
  localBuildPathRank = update.rank;
  updateLevelUpCallingGuide();
  combatHud.setCalling(update.selectedPathId, update.selectedCallingAbilityId, update.rank, update.selectedCallingAugmentId,
    update.callingAugmentProgress, update.masteredCallingAugments);
  refreshCallingUnlockNotice();
  updateTouchAbilityVisibility();
  updateControlsHelp();
  if (trackedCodexItemId) setCodexHunt(trackedCodexItemId, false);
  const selected = update.selectedPathId ? BUILD_PATHS[update.selectedPathId] : null;
  const rank = BUILD_PATH_RANKS.find(entry => entry.rank === update.rank) ?? BUILD_PATH_RANKS[0];
  buildPathPanel.dataset.selected = update.selectedPathId ?? "unbound";
  buildPathPanel.dataset.available = String(update.canChoose);
  buildPathName.textContent = selected?.name.toUpperCase() ?? "UNBOUND";
  const selectedSpecialization = update.selectedPathId && update.selectedSpecializationId
    ? BUILD_PATH_SPECIALIZATIONS[update.selectedPathId].find(option => option.id === update.selectedSpecializationId) : null;
  buildPathRank.textContent = selected ? `${rank.name.toUpperCase()} · RANK ${update.rank}${selectedSpecialization ? ` · ${selectedSpecialization.name.toUpperCase()}` : ""}`
    : "CHOOSE YOUR CALLING";
  const activeAbility = update.selectedCallingAbilityId
    ? CALLING_ABILITY_OPTIONS.find(option => option.id === update.selectedCallingAbilityId) : null;
  if (update.selectedPathId !== "assassin") buildPathMessage.textContent = selected && activeAbility
    ? `${activeAbility.name} ${localCharacterProgression.level >= 2 ? "is ready on G" : "unlocks on G at level 2"}. Your Calling Special ${localCharacterProgression.level >= 4 ? "is on F" : "unlocks on F at level 4"}.`
    : "Choose one combat identity. You can change it later while in Town.";
  const previousThreshold = BUILD_PATH_RANKS.find(entry => entry.rank === update.rank)?.xp ?? 0;
  const span = Math.max(1, (update.nextRankXp ?? previousThreshold) - previousThreshold);
  const progress = update.nextRankXp === null ? 1 : Math.max(0, Math.min(1, (update.xp - previousThreshold) / span));
  buildPathProgress.toggleAttribute("hidden", !selected);
  buildPathProgress.querySelector<HTMLElement>("i")!.style.width = `${Math.round(progress * 100)}%`;
  buildPathProgress.setAttribute("aria-label", update.nextRankXp === null ? "Master rank complete" : `${update.xp} of ${update.nextRankXp} Path Mastery`);
  const nextRank = BUILD_PATH_RANKS.find(entry => entry.rank > update.rank);
  buildPathNext.textContent = selected
    ? update.nextRankXp === null ? "Mastery complete" : `${update.xp}/${update.nextRankXp} mastery · Next: ${nextRank?.name ?? "Master"}`
    : "Six Callings available";
  buildPathOpen.textContent = selected ? update.canChoose ? "VIEW CALLING" : "CHANGE IN TOWN"
    : update.canChoose ? "CHOOSE CALLING" : "CHOOSE ON SURFACE";
  buildPathOpen.disabled = !update.canChoose;
  const callingRequired = !update.selectedPathId;
  callingIntroClose.hidden = callingRequired;
  callingIntroLater.hidden = callingRequired;
  buildPathCandidates.replaceChildren();
  const specializationList = buildPathSpecializations.querySelector<HTMLElement>("div")!;
  specializationList.replaceChildren();
  buildPathSpecializations.hidden = !selected || update.rank < 3;
  if (selected && update.selectedPathId && update.rank >= 3) for (const specialization of BUILD_PATH_SPECIALIZATIONS[update.selectedPathId]) {
    const button = document.createElement("button"); button.type = "button";
    button.dataset.active = String(specialization.id === update.selectedSpecializationId);
    button.innerHTML = `<strong>${specialization.name}</strong><small>${specialization.role}</small><span>${specialization.effect}</span>`;
    button.disabled = Boolean(update.selectedSpecializationId) || !update.canSpecialize || !update.inTown;
    button.title = update.selectedSpecializationId ? "Veteran path already bound" : update.inTown ? `Bind the ${specialization.name} path` : "Return to Town to specialize";
    button.addEventListener("click", () => room?.send("build:path", { action: "specialize", specializationId: specialization.id }));
    specializationList.append(button);
  }
  buildPathMasterTrial.hidden = !update.masterTrial;
  if (update.masterTrial) {
    buildPathMasterTrial.dataset.complete = String(update.masterTrial.complete);
    buildPathMasterTrial.querySelector("b")!.textContent = update.masterTrial.complete ? "MASTERED" : `${update.masterTrial.progress} / ${update.masterTrial.target}`;
    buildPathMasterTrial.querySelector("p")!.textContent = update.masterTrial.description;
    buildPathMasterTrial.querySelector<HTMLElement>("i")!.style.width = `${Math.round(update.masterTrial.progress / update.masterTrial.target * 100)}%`;
    buildPathMasterTrial.querySelector("small")!.textContent = update.masterTrial.complete ? update.masterTrial.capstone : `CAPSTONE · ${update.masterTrial.capstone}`;
  }
  if (!update.canChoose) {
    callingIntro.hidden = true;
    if (update.selectedPathId && previousPathId !== update.selectedPathId) {
      sessionStorage.setItem("calling-intro-seen-v1", "true");
      status.textContent = `${selected!.name} Calling chosen. ${localCharacterProgression.level >= 2 ? `Press G to use ${activeAbility?.name ?? "your Power"}` : `${activeAbility?.name ?? "Your Power"} unlocks at level 2`}.`;
      if (pendingCallingChoicePathId === update.selectedPathId || callingFirstOnboardingPending)
        beginCallingAwakening(update.selectedPathId, activeAbility?.name ?? "Calling Power");
      else showCombatFeedback(`${selected!.name.toUpperCase()} · ${localCharacterProgression.level >= 2 ? "PRESS G" : "POWER AT LV 2"}`, "dodge");
      pendingCallingChoicePathId = null;
    }
    return;
  }
  callingIntroTitle.textContent = selected ? "Your Calling" : "Choose your Calling";
  callingIntroEyebrow.textContent = selected ? `${selected.name.toUpperCase()} · ${rank.name.toUpperCase()}` : "YOUR PLAYSTYLE HAS AWAKENED";
  callingIntroCopy.textContent = selected
    ? "Review gear-based paths, or choose Healer for team support. Changes are allowed only in Town."
    : "Choose your first combat style here. Its Power unlocks at level 2 and Special at level 4. Changes later require Town.";
  update.candidates.forEach((candidate, index) => {
    const definition = BUILD_PATHS[candidate.pathId];
    const starter = CALLING_ABILITY_OPTIONS.find(option => option.pathId === candidate.pathId && option.unlockRank === 0)!;
    const button = document.createElement("button"); button.type = "button";
    button.dataset.path = candidate.pathId;
    button.dataset.active = String(candidate.pathId === update.selectedPathId);
    button.dataset.recommended = String(index === 0);
    const why = candidate.reasons.length ? candidate.reasons.join(" · ") : "a flexible starting loadout";
    const awakening = callingAwakening(candidate.pathId);
    button.innerHTML = `<em>${candidate.pathId === update.selectedPathId ? "CURRENT" : index === 0 ? "RECOMMENDED" : "OPTION"}</em>${callingPreviewMarkup(candidate.pathId, definition.name)}<span><strong>${definition.name}</strong><small>${definition.role}</small></span><p class="calling-preview-caption">${awakening.action}</p><b>${starter.name} · unlocks at LV 2</b><small>${starter.description}</small>`;
    button.style.setProperty("--calling-colour", awakening.colour);
    button.style.setProperty("--calling-accent", awakening.accent);
    button.dataset.previewing = String(index === 0);
    button.disabled = !update.canChoose || Boolean(update.selectedPathId && !update.inTown);
    button.title = button.disabled ? "Return to Town to change your Calling" : `Choose ${definition.name}`;
    button.addEventListener("pointerenter", () => focusCallingPreview(button));
    button.addEventListener("focus", () => focusCallingPreview(button));
    button.addEventListener("click", () => {
      if (!room || !update.canChoose || (update.selectedPathId && !update.inTown)) return;
      for (const candidateButton of buildPathCandidates.querySelectorAll<HTMLButtonElement>("button")) candidateButton.disabled = true;
      callingIntroStatus.textContent = `Accepting the ${definition.name} Calling…`;
      pendingCallingChoicePathId = candidate.pathId;
      room.send("build:path", { action: "choose", pathId: candidate.pathId as BuildPathId });
    });
    buildPathCandidates.append(button);
  });
  callingIntroStatus.textContent = !update.selectedPathId
    ? "Choose your first Calling now. Future changes are made in Town."
    : "Recommended reflects the gear and stats you use now. You can change later in Town.";
  if (update.selectedPathId && previousPathId !== update.selectedPathId) {
    callingIntro.hidden = true;
    sessionStorage.setItem("calling-intro-seen-v1", "true");
    status.textContent = `${selected!.name} Calling chosen. ${localCharacterProgression.level >= 2 ? `Press G to use ${activeAbility?.name ?? "your Power"}` : `${activeAbility?.name ?? "Your Power"} unlocks at level 2`}.`;
    if (pendingCallingChoicePathId === update.selectedPathId || callingFirstOnboardingPending)
      beginCallingAwakening(update.selectedPathId, activeAbility?.name ?? "Calling Power");
    else showCombatFeedback(`${selected!.name.toUpperCase()} · ${localCharacterProgression.level >= 2 ? "PRESS G" : "POWER AT LV 2"}`, "dodge");
    pendingCallingChoicePathId = null;
  } else if (!update.selectedPathId && update.canChoose && levelUpPanel.hidden) {
    openCallingIntro();
  }
  if (!inventoryPanel.hidden && selectedInventoryItem) {
    inventoryComparisonKey = "";
    refreshInventoryPreview();
  }
}

function openCallingIntro(): void {
  if (buildPathOpen.disabled) return;
  if (!inventoryPanel.hidden) setInventoryOpen(false);
  callingIntro.hidden = false;
  sessionStorage.setItem("calling-intro-seen-v1", "true");
  resetMovementControls();
  window.setTimeout(() => buildPathCandidates.querySelector<HTMLButtonElement>('button[data-recommended="true"]')?.focus(), 0);
}

function closeCallingIntro(): void {
  if (!localBuildPathId) return;
  callingIntro.hidden = true;
  if (!localBuildPathId && localCharacterProgression.level >= 2) {
    dismissedCallingLevel = localCharacterProgression.level;
    progressionNoticeQuietUntil = performance.now() + 8_000;
    refreshProgressionNotice();
  }
  if (!inventoryPanel.hidden) buildPathOpen.focus(); else canvas.focus();
}
buildPathOpen.addEventListener("click", openCallingIntro);
callingIntroClose.addEventListener("click", closeCallingIntro);
callingIntroLater.addEventListener("click", closeCallingIntro);
buildPathCandidates.addEventListener("keydown", event => {
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.code)) return;
  const buttons = [...buildPathCandidates.querySelectorAll<HTMLButtonElement>("button:not(:disabled)")];
  const current = buttons.indexOf(document.activeElement as HTMLButtonElement);
  if (current < 0 || buttons.length < 2) return;
  const columns = window.matchMedia("(max-width: 720px)").matches ? 1 : 3;
  const offset = event.code === "ArrowLeft" ? -1 : event.code === "ArrowRight" ? 1
    : event.code === "ArrowUp" ? -columns : columns;
  buttons[(current + offset + buttons.length) % buttons.length]?.focus();
  event.preventDefault();
});

function updateMomentum(stacksValue: number): void {
  const safeStacks = Number.isFinite(stacksValue) ? stacksValue : 0;
  localMomentumStacks = Math.max(0, Math.min(MOMENTUM_TRAIT.maxStacks, Math.floor(safeStacks)));
  momentumPips.forEach((pip, index) => pip.classList.toggle("active", index < localMomentumStacks));
  traitSlot.setAttribute("aria-label", localTraitId === "momentum"
    ? `${MOMENTUM_TRAIT.name} trait, ${localMomentumStacks} of ${MOMENTUM_TRAIT.maxStacks} stacks`
    : `${TRAIT_DEFINITIONS[localTraitId].name} trait. ${TRAIT_DEFINITIONS[localTraitId].description}`);
  traitSlot.dataset.stacks = String(localMomentumStacks);
}

function localMovementSpeed(): number {
  const fastWorldMultiplier = fastWorldRequested ? 1.38 : 1;
  const baseSpeed = (localDefending ? 2.1 : 4.2) * fastWorldMultiplier * armourStats(localArmourId).speed;
  const traitSpeed = localTraitId === "momentum"
    ? baseSpeed * (1 + localMomentumStacks * MOMENTUM_TRAIT.movementSpeedBonusPerStack)
    : baseSpeed;
  return traitSpeed * characterSpeedMultiplier(localCharacterProgression.agilityPoints);
}

const DANGER_ZONE_LABELS = [
  { name: "TOWN OF BEGINNINGS", detail: "Protected sanctuary · enemies cannot attack here" },
  { name: "OUTSKIRTS", detail: "Standard enemies and standard rewards" },
  { name: "WILDS", detail: "Tougher, faster enemies · improved rewards" },
  { name: "DEEP FRONTIER", detail: "Elite enemies · highest danger and rewards" },
] as const;

let localDangerTier = 0;
let dangerZoneKey = "";

function updateDangerZone(tierValue: number, position = localPlayer.getPosition()): void {
  const coordinates = `XYZ: ${Math.floor(position.x)} / ${Math.floor(position.y)} / ${Math.floor(position.z)}`;
  if (locationCoordinates.textContent !== coordinates) locationCoordinates.textContent = coordinates;
  const tier = Math.max(0, Math.min(3, Math.floor(tierValue)));
  localDangerTier = tier;
  const greenwood = tier > 0 && isInGreenwoodRegion(position.x, position.z);
  const camp = tier > 0 && isInGreenwoodCamp(position.x, position.z);
  const arena = tier > 0 && isInStoneBruteArena(position.x, position.z);
  const territory = position.y >= SURFACE_HEIGHT && tier > 0 ? wildernessTerritoryAt(position.x, position.z) : null;
  const silverGuard = position.y >= SURFACE_HEIGHT && isInSilverGuardClearing(position.x, position.z);
  const frontierArena = position.y >= SURFACE_HEIGHT && isInFrontierBruteArena(position.x, position.z);
  const realmWardenArena = position.y >= SURFACE_HEIGHT && isInRealmWardenArena(position.x, position.z);
  const dungeonAtmosphere = forestDungeonAtmosphere(position.x, position.z);
  const forestDungeon = dungeonAtmosphere.room > 0;
  const silverDepths = position.y < 6 && position.x >= SILVER_DEPTHS.minX - .5 && position.x <= SILVER_DEPTHS.maxX + 1.5
    && position.z >= SILVER_DEPTHS.minZ - 1 && position.z <= SILVER_DEPTHS.maxZ + 1;
  const depthsZone = silverDepths ? silverDepthsZone(position) : null;
  const depthsProfile = depthsZone ? SILVER_DEPTHS_ATMOSPHERES[depthsZone] : null;
  const emberVault = isInEmberVault(position.x, position.z);
  const dungeonDetail = dungeonAtmosphere.room === 1 ? "Split the rootbound crawlers · the return portal remains behind you"
    : dungeonAtmosphere.room === 2 ? "Use stone cover · read aimed shots and fan gaps"
      : "Root volleys become committed charges below half health";
  const label = emberVault ? { name: position.x >= 232 ? "COLOSSUS FORGE" : position.x >= 223 ? "EMBER CRUCIBLE" : "THE EMBER VAULT", detail: position.x >= 232 ? "Read the Colossus · dodge the committed smash · claim its forge loot" : "Use iron pillars as cover · clear each sealed forge chamber" }
    : depthsProfile ? { name: depthsProfile.name, detail: depthsProfile.detail }
    : forestDungeon ? { name: dungeonAtmosphere.name, detail: dungeonDetail } : realmWardenArena ? { name: "REALM WARDEN COURT", detail: "Use the four stone pillars · read the marked impacts · punish the Warden between volleys" } : frontierArena ? { name: "FRONTIER BRUTE RUINS", detail: "Sidestep the smash · leave the slam circle · counter during recovery · rich silver and a guaranteed hammer" } : silverGuard ? { name: "SILVER GUARD CLEARING", detail: "Two alternating spitters · use stone cover and fan gaps · dirt trail leads west to the south gate" } : arena ? { name: "STONE BRUTE CLEARING", detail: "One heavy opponent · dodge the marked slam · collect a Stone Core Hammer on defeat" }
    : camp ? { name: "GREENWOOD CRAWLER CAMP", detail: "Three roaming crawlers · exposed iron on the east edge · defeat mobs and collect item drops" } : greenwood
    ? { name: "GREENWOOD OUTSKIRTS", detail: "Ancient oaks · harvest timber · Briar Crawlers roam the camp" }
    : territory ?? DANGER_ZONE_LABELS[tier]!;
  const recommendedLevel = emberVault ? position.x >= 232 ? "LV 14–16" : "LV 12–14"
    : tier === 0 ? "SAFE"
      : silverDepths ? depthsZone === "arena" ? "LV 10–12" : "LV 7–10"
      : forestDungeon ? dungeonAtmosphere.room === 3 ? "LV 10–12" : dungeonAtmosphere.room === 2 ? "LV 8–10" : "LV 6–8"
        : frontierArena ? "LV 9–12" : silverGuard ? "LV 5–8" : arena ? "LV 4–6" : worldLevelRange(territory?.tier ?? tier).label;
  const nextKey = `${tier}:${greenwood}:${camp}:${arena}:${silverGuard}:${frontierArena}:${dungeonAtmosphere.room}:${territory?.name ?? ""}:${depthsZone}:${emberVault}:${recommendedLevel}`;
  if (nextKey === dangerZoneKey) return;
  dangerZoneKey = nextKey;
  dangerZone.dataset.tier = String(tier);
  dangerZoneName.textContent = label.name;
  dangerZoneTier.textContent = recommendedLevel;
  dangerZoneDetail.textContent = `${label.detail} · Recommended ${recommendedLevel}`;
}

function actionDuration(step: number): number {
  if (step < 1 || step > 3 || localActionMainHandId === null) return PRIMARY_ACTION_DURATION_MS;
  return rapidCombatDuration(WEAPON_ATTACK_DEFINITIONS[localActionMainHandId].attacks[step - 1]?.durationMs ?? PRIMARY_ACTION_DURATION_MS,
    fastWorldRequested, rapidPracticeHaste);
}

function remoteActionDuration(mainHandId: MainHandId | null, step: number): number {
  if (!mainHandId || step < 1 || step > 3) return PRIMARY_ACTION_DURATION_MS;
  return rapidCombatDuration(WEAPON_ATTACK_DEFINITIONS[mainHandId].attacks[step - 1]?.durationMs ?? PRIMARY_ACTION_DURATION_MS,
    fastWorldRequested, rapidPracticeHaste);
}

function powerDuration(powerId: PowerId | null): number {
  if (!powerId) return 0;
  const definition = POWER_DEFINITIONS[powerId];
  return definition.windupMs + definition.activeMs + definition.recoveryMs;
}

function showCombatFeedback(text: string, style: "hit" | "hurt" | "dodge" | "miss" | "block" | "stagger" = "hit"): void {
  combatFeedback.textContent = text;
  combatFeedback.classList.remove("show", "hurt", "dodge", "miss", "block", "stagger");
  void combatFeedback.offsetWidth;
  if (style !== "hit") combatFeedback.classList.add(style);
  combatFeedback.classList.add("show");
}

let rangedReticleHitUntil = 0;
let rangedPopupSequence = 0;
const rangedPopups: { element: HTMLElement; position: pc.Vec3; startedAt: number; duration: number; damage: boolean; offset: number }[] = [];
let northwatchPatrolCueArmed = true;
function updateNorthwatchPatrolCue(player: pc.Vec3): void {
  const site = NORTHWATCH_SHARD_PATROL_SITE;
  const distance = Math.hypot(player.x - site.x, player.z - site.z);
  if (player.y < SURFACE_HEIGHT || distance > 24) { northwatchPatrolCueArmed = true; return; }
  if (!northwatchPatrolCueArmed || distance > 14 || ![
    "northwatch-spitter", "northwatch-patrol-stalker-west", "northwatch-patrol-stalker-east",
  ].some(id => mobVisuals.get(id)?.state.alive)) return;
  northwatchPatrolCueArmed = false;
  createRangedPopup(new pc.Vec3(site.x, site.y + 1.8, site.z), "SHARD PATROL · CLEAR ALL THREE", "landmark");
}
function createRangedPopup(position: pc.Vec3, text: string, kind: "damage" | "melee" | "stagger" | "enemy" | "terrain" | "near-miss" | "landmark", defeated = false, color?: readonly number[]): void {
  const element = document.createElement("span");
  element.className = `ranged-popup ranged-popup-${kind}${defeated ? " defeated" : ""}`;
  element.textContent = text; element.setAttribute("aria-hidden", "true");
  if (color) element.style.color = `rgb(${color.map(channel => Math.round(channel * 255)).join(",")})`;
  document.body.append(element);
  const combatCue = kind === "damage" || kind === "melee" || kind === "stagger";
  rangedPopups.push({ element, position: position.clone(), startedAt: performance.now(), duration: kind === "landmark" ? 2_000 : combatCue ? 800 : kind === "near-miss" ? 160 : 240,
    damage: combatCue, offset: combatCue ? (++rangedPopupSequence % 3 - 1) * 14 : 0 });
  while (rangedPopups.length > 32) rangedPopups.shift()!.element.remove();
}
function updateRangedFeedback(now: number): void {
  const hit = now < rangedReticleHitUntil;
  if (combatReticle.dataset.hit !== String(hit)) combatReticle.dataset.hit = String(hit);
  if (!rangedPopups.length) return;
  const rect = canvas.getBoundingClientRect();
  for (let index = rangedPopups.length - 1; index >= 0; index--) {
    const popup = rangedPopups[index]!, fraction = (now - popup.startedAt) / popup.duration;
    if (fraction >= 1 || !worldReady) { popup.element.remove(); rangedPopups.splice(index, 1); continue; }
    const screen = camera.camera?.worldToScreen(popup.position);
    popup.element.hidden = !screen || screen.z <= 0 || screen.x < 0 || screen.y < 0 || screen.x > rect.width || screen.y > rect.height;
    if (popup.element.hidden || !screen) continue;
    popup.element.style.left = `${rect.left + screen.x + popup.offset}px`;
    popup.element.style.top = `${rect.top + screen.y - (popup.damage ? fraction * 38 : 0)}px`;
    popup.element.style.opacity = String(Math.min(1, (1 - fraction) * 2));
    popup.element.style.transform = `translate(-50%, -50%) scale(${popup.damage ? 1 + Math.max(0, .15 - fraction) : .65 + fraction * .7})`;
  }
}

