targetMarker.enabled = false;
app.root.addChild(targetMarker);

const initialCanvasBounds = canvas.getBoundingClientRect();
const pointer = { x: initialCanvasBounds.width / 2, y: initialCanvasBounds.height / 2 };
const rangedPointer = { active: false, x: 0, y: 0 };
let rangedFirePointer: number | null = null;
let touchCameraPointerId: number | null = null;
let touchCameraStart = { x: 0, y: 0 };
let touchCameraLast = { x: 0, y: 0 };
let touchCameraLastAt = 0;
let touchCameraDragged = false;
let touchCameraPinched = false;
let touchCameraPinchSpan: number | null = null;
const touchCameraPoints = new Map<number, { x: number; y: number }>();
const TABLET_CAMERA_HINT_STORAGE_KEY = "blockcraft-tablet-camera-hint-v1";
let tabletCameraHintSeen = (() => {
  try { return window.localStorage.getItem(TABLET_CAMERA_HINT_STORAGE_KEY) === "seen"; } catch { return false; }
})();
const tabletCameraHintEligibleAt = performance.now() + 1_800;
let keyboardFireHeld = false;

function completeTabletCameraHint(): void {
  if (tabletCameraHintSeen) return;
  tabletCameraHintSeen = true;
  tabletCameraHint.hidden = true;
  try { window.localStorage.setItem(TABLET_CAMERA_HINT_STORAGE_KEY, "seen"); } catch { /* Storage may be disabled. */ }
}

function updateTabletCameraHint(now = performance.now()): void {
  tabletCameraHint.hidden = tabletCameraHintSeen || !tabletControlsQuery.matches || !worldReady
    || now < tabletCameraHintEligibleAt || tabletHudCombatActive || popupQueue.active() !== null;
}

function updateKeyboardCameraHint(): void {
  keyboardCameraHint.hidden = !shouldShowKeyboardCameraHint({
    worldReady,
    inTown: isAtTownOfBeginnings(),
    level: localCharacterProgression.level,
    coarsePointer: tabletControlsQuery.matches,
    dialogOpen: reportedProtectedDialog === true || popupQueue.active() !== null,
    competingNoticeOpen: !progressionNoticePanel.hidden || !callingFirstUse.hidden,
  });
  for (const key of keyboardCameraKeys) key.dataset.active = String(keys.has(key.dataset.key ?? ""));
}

function saveTabletCameraZoom(): void {
  try { window.localStorage.setItem(CAMERA_ZOOM_STORAGE_KEY, cameraOrbit.distance.toFixed(3)); } catch { /* Storage may be disabled. */ }
}
function rangedFireAllowed(requirePointerAim = true): boolean {
  const combatMenuPanels = [inventoryPanel, lootPanel, defeatScreen, quizPanel, blacksmithPanel, tavernDialogue,
    ...(rapidPracticeRewardPanel ? [rapidPracticeRewardPanel] : [])];
  return Boolean(room && worldReady && (interactionMode === "combat" || !requirePointerAim)
    && (!requirePointerAim || rangedPointer.active) && !document.hidden
    && continuousAttackEnabled(WEAPON_ATTACK_DEFINITIONS[localMainHandId].projectileTravelMs > 0, fastWorldRequested)
    && combatMenuPanels.every(panel => panel.hidden === true) && !tradeUI.isOpen() && !playerInteractionUI.isOpen()
    && !(document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement)
    && !powerAimActive && !specialAimActive && localPowerStartedAt === null && !localDefending);
}
function mouseRangedYaw(fallback: number): number {
  if (cameraViewMode === "first-person") return firstPersonFacingYaw(cameraOrbit.yaw);
  if (!rangedPointer.active || !camera.camera) return fallback;
  const rect = canvas.getBoundingClientRect();
  const x = rangedPointer.x - rect.left, y = rangedPointer.y - rect.top;
  return rangedAimYaw(camera.camera.screenToWorld(x, y, camera.camera.nearClip), camera.camera.screenToWorld(x, y, camera.camera.farClip), localPlayer.getPosition(), fallback);
}
function updateRangedReticle(): void {
  const continuous = continuousAttackEnabled(WEAPON_ATTACK_DEFINITIONS[localMainHandId].projectileTravelMs > 0, fastWorldRequested);
  const active = rangedPointer.active && continuous && interactionMode === "combat" && worldReady && defeatScreen.hidden === true && inventoryPanel.hidden === true;
  combatReticle.hidden = !active;
  canvas.classList.toggle("ranged-aim", active);
  if (active) {
    combatReticle.style.left = cameraViewMode === "first-person" ? "50vw" : `${rangedPointer.x}px`;
    combatReticle.style.top = cameraViewMode === "first-person" ? "50vh" : `${rangedPointer.y}px`;
  }
}
