function setInventoryOpen(open: boolean): void {
  if (!open && localMainHandId === "forged_sword") {
    if (forcedStarterEquipment) completeStarterEquipment();
    if (firstStepsIndex === ONBOARDING_STAGE.equipSword) noteFirstStep("equipped_starter");
  }
  const starterLesson = starterInventoryLesson(
    firstStepsIndex,
    starterInventoryOpenedWithKeyboard,
    forcedStarterEquipment,
    localMainHandId,
  );
  if (open && starterLesson === "open_pack") {
    status.textContent = "Press I to open your inventory and equip the starter sword.";
    nudgeStarterInventoryTutorial();
    return;
  }
  if (firstVictoryRewardLessonReady() && open && firstVictoryReward?.stage === "open_pack") {
    status.textContent = "Press I to open your pack and inspect your Calling-matched reward.";
    nudgeStarterInventoryTutorial();
    return;
  }
  if (open) closeLoot();
  profileControls.hidden = true;
  adventureConfirm.hidden = true;
  inventoryProfile.setAttribute("aria-expanded", "false");
  inventoryPanel.hidden = !open;
  delete inventoryPanel.dataset.storage;
  document.querySelector("#inventory-title")!.textContent = "Inventory";
  document.querySelector<HTMLElement>("#personal-storage")!.hidden = true;
  inventoryToggle.setAttribute("aria-expanded", String(open));
  if (open) {
    closeTavernDialogue();
    room?.send("build:path", { action: "sync" });
    inventoryPreviewDrawer.open = inventoryPanel.dataset.tab === "gear";
    refreshOwnedInventory();
    inventoryPanel.scrollTop = 0;
    previewHand = undefined; previewArmour = undefined; selectedInventoryItem = undefined;
    previewSlot = inventoryTabs.find(tab => tab.getAttribute("aria-selected") === "true")?.dataset.inventoryTab === "armour" ? "armour" : "weapon";
    refreshInventoryPreview();
    performancePanel.hidden = true;
    performanceToggle.setAttribute("aria-expanded", "false");
    resetMovementControls();
    if (firstVictoryReward?.stage === "choose" && isItemId(firstVictoryReward.itemId)) {
      selectInventoryCategory("gear");
      window.setTimeout(() => {
        const card = inventoryPanel.querySelector<HTMLElement>(`[data-item="${firstVictoryReward?.itemId}"]`);
        card?.click();
        inventorySelectedEquip.focus();
        inventoryDecisionPanel.scrollIntoView({ block: "nearest" });
      }, 0);
    } else if (starterLesson === "equip_sword") {
      selectInventoryCategory("gear");
      window.setTimeout(() => {
        const card = inventoryPanel.querySelector<HTMLElement>('[data-item="forged_sword"]');
        card?.click();
        card?.querySelector<HTMLButtonElement>("[data-equip-main-hand]")?.focus();
      }, 0);
    } else inventoryClose.focus();
  } else {
    inventoryPortrait?.hide();
    app.autoRender = true;
    inventoryToggle.focus();
  }
}

