function updatePerformanceLogStatus(message?: string): void {
  performanceLogStatus.textContent = message ?? `Logging locally · ${performanceLogSamples.length} samples · rolling 10 minutes`;
}

function persistPerformanceLog(): void {
  try { window.localStorage.setItem(PERFORMANCE_LOG_STORAGE_KEY, JSON.stringify(performanceLogSamples)); }
  catch { updatePerformanceLogStatus("Local logging unavailable in this browser"); }
}

function markPerformanceAnomaly(marker: string): void {
  pendingPerformanceMarkers.add(marker);
}

function capturePerformancePeak(key: keyof typeof performancePeaks, value: number): void {
  if (Number.isFinite(value)) performancePeaks[key] = Math.max(performancePeaks[key], value);
}

try {
  const longTaskObserver = new PerformanceObserver(entries => {
    for (const entry of entries.getEntries()) recentLongTaskPeakMs = Math.max(recentLongTaskPeakMs, entry.duration);
  });
  longTaskObserver.observe({ entryTypes: ["longtask"] });
} catch { /* Long Task API is not available in every browser. */ }

try {
  type LongAnimationFrameEntry = PerformanceEntry & {
    blockingDuration?: number;
    renderStart?: number;
    styleAndLayoutStart?: number;
  };
  const longFrameObserver = new PerformanceObserver(entries => {
    for (const rawEntry of entries.getEntries()) {
      const entry = rawEntry as LongAnimationFrameEntry;
      const frameEnd = entry.startTime + entry.duration;
      recentLoafDurationMs = Math.max(recentLoafDurationMs, entry.duration);
      recentLoafBlockingMs = Math.max(recentLoafBlockingMs, entry.blockingDuration ?? 0);
      if (entry.renderStart !== undefined)
        recentLoafRenderDelayMs = Math.max(recentLoafRenderDelayMs, entry.renderStart - entry.startTime);
      if (entry.styleAndLayoutStart !== undefined)
        recentLoafStyleLayoutMs = Math.max(recentLoafStyleLayoutMs, frameEnd - entry.styleAndLayoutStart);
    }
  });
  longFrameObserver.observe({ entryTypes: ["long-animation-frame"] });
} catch { /* Long Animation Frame API is Chromium-only and may be disabled. */ }

updatePerformanceLogStatus();

function trackMovementInput(sequence: number, now = performance.now()): void {
  movementSentAt.set(sequence, now);
  while (movementSentAt.size > 180) movementSentAt.delete(movementSentAt.keys().next().value!);
}

function recordMovementAcknowledgement(sequence: number, now = performance.now()): void {
  const sentAt = movementSentAt.get(sequence);
  if (sentAt !== undefined) inputAcknowledgementMs = now - sentAt;
  for (const pending of movementSentAt.keys()) if (pending <= sequence) movementSentAt.delete(pending);
}

function incomingMessageBytes(data: unknown): number {
  if (typeof data === "string") return new TextEncoder().encode(data).byteLength;
  if (data instanceof ArrayBuffer) return data.byteLength;
  if (ArrayBuffer.isView(data)) return data.byteLength;
  if (typeof Blob !== "undefined" && data instanceof Blob) return data.size;
  return 0;
}

function bindNetworkPerformance(joinedRoom: Room): void {
  const transport = joinedRoom.connection.transport as unknown as { ws?: WebSocket };
  const socket = transport.ws;
  if (!socket?.addEventListener || instrumentedSockets.has(socket)) return;
  instrumentedSockets.add(socket);
  socket.addEventListener("message", event => {
    const data = event.data;
    incomingBytesWindow += incomingMessageBytes(data);
    if (data instanceof ArrayBuffer && data.byteLength > 0 && (new Uint8Array(data)[0]! & 0x1f) === 15) incomingPatchWindow++;
    else if (ArrayBuffer.isView(data) && data.byteLength > 0
      && (new Uint8Array(data.buffer, data.byteOffset, data.byteLength)[0]! & 0x1f) === 15) incomingPatchWindow++;
    else if (typeof Blob !== "undefined" && data instanceof Blob && data.size > 0)
      void data.slice(0, 1).arrayBuffer().then(buffer => {
        if ((new Uint8Array(buffer)[0]! & 0x1f) === 15) incomingPatchWindow++;
      });
  });
}

function renderBootstrap(payload: WorldBootstrap): void {
  clearPendingStatChoice();
  caveDiscoverySampleKey = "";
  caveFogViewKey = "";
  caveDiscoveryRevision++;
  miningSwing = null;
  pendingMine = null;
  miningHud.hidden = true;
  closeTavernDialogue();
  blacksmithPanel.hidden = true;
  inventoryPanel.hidden = true;
  inventoryToggle.setAttribute("aria-expanded", "false");
  const buildStartedAt = performance.now();
  const previousSliceY = cutawaySliceY;
  worldPayloadBytes = new Blob([JSON.stringify(payload)]).size;
  for (const chunk of chunks.values()) for (const mesh of chunk.meshes) mesh.destroy();
  for (const child of [...worldRoot.children]) child.destroy();
  chunks.clear();
  queuedChunkRebuilds.clear();
  payload.chunks.forEach(installChunk);
  const ownPlayer = room ? (room.state as { players?: { get(id: string): NetworkPlayer | undefined } }).players?.get(room.sessionId) : undefined;
  // The bootstrap is the authoritative arrival snapshot. The schema player can
  // still represent a different patch when a newly created room first joins.
  const initialPose = townReturnPosition ?? payload.spawn;
  const statePoseGap = ownPlayer
    ? Math.hypot(ownPlayer.x - payload.spawn.x, ownPlayer.y - payload.spawn.y, ownPlayer.z - payload.spawn.z)
    : null;
  townReturnPosition = null;
  const initialPosition = new pc.Vec3(initialPose.x, initialPose.y, initialPose.z);
  localPlayer.setPosition(initialPosition.x, initialPosition.y, initialPosition.z);
  authoritativeLocalPosition.set(initialPosition.x, initialPosition.y, initialPosition.z);
  cameraFocus.set(initialPosition.x, initialPosition.y, initialPosition.z);
  cameraFollow = { x: initialPosition.x, z: initialPosition.z };
  const cameraOffset = cameraOrbitOffset(cameraOrbit);
  camera.setPosition(initialPosition.x + cameraOffset.x, initialPosition.y - 2 + cameraOffset.y, initialPosition.z + cameraOffset.z);
  camera.lookAt(initialPosition.x, initialPosition.y - 2, initialPosition.z);
  localVerticalVelocity = 0;
  localVisualVerticalOffset = 0;
  localNetworkVisualOffset = { x: 0, z: 0 };
  localRecoveryVisualOffset = { x: 0, z: 0 };
  localDodgeVisualOffset = { x: 0, z: 0 };
  localDodgeRequestedAt = Number.NEGATIVE_INFINITY;
  localDodgeChain = 0;
  localDodgeExhaustedUntil = 0;
  pendingPredictionFrames.length = 0;
  unsentMovementSteps.length = 0;
  blockedAcknowledgements = 0;
  lastAuthoritativeDodgeSequence = ownPlayer?.dodgeSequence ?? 0;
  smoothedMovement = { x: 0, z: 0 };
  lastSentMovement = { x: 0, z: 0 };
  pendingStopInputSequence = null;
  localPowerVisualOffset.set(0, 0, 0);
  localPlayerVisual.setLocalPosition(0, 0, 0);
  surfaceReferenceY = SURFACE_HEIGHT + 1;
  indoorRoofBuilding = roofCutawayBuilding(initialPosition, null, TOWN_BUILDINGS, surfaceReferenceY);
  indoorCameraBlend = indoorRoofBuilding ? 1 : 0;
  const bootstrapUnderground = indoorRoofBuilding === null && hasCeilingAbove(initialPosition);
  const bootstrapExcavating = indoorRoofBuilding === null && !bootstrapUnderground && isInOpenExcavation(initialPosition);
  cutawaySliceY = bootstrapSliceHeight(
    previousSliceY,
    initialPosition.y,
    surfaceReferenceY,
    bootstrapUnderground,
    bootstrapExcavating,
  );
  playerCutaway.active = cutawaySliceY !== null;
  playerCutaway.sliceY = cutawaySliceY ?? CHUNK_HEIGHT;
  cutawayStateKey = cutawaySliceY === null ? "surface" : `slice:${cutawaySliceY}`;
  surfaceReturnStartedAt = null;
  surfaceRestoreStartSliceY = null;
  undergroundLightingBlend = playerCutaway.active ? 1 : 0;
  exitTrail.enabled = playerCutaway.active;
  exitGuide.hidden = !playerCutaway.active;
  activeChunkViewKey = null;
  updateActiveChunkMeshes(initialPosition);
  // Make the arrival tile available immediately; the remaining visible area
  // fills nearest-first over subsequent frames.
  processNextChunkRebuild(initialPosition);
  const initialChunk = worldToChunk(initialPosition.x, initialPosition.z);
  const initialChunkKey = chunkKey(initialChunk.chunkX, initialChunk.chunkZ);
  requestedChunkRegionKey = chunks.has(initialChunkKey) ? initialChunkKey : null;
  if (!fastWorldRequested) {
    sceneDressing.rebuild(readWorldBlock, payload.chunks, indoorRoofBuilding);
    sceneDressing.setSurfaceVisible(!playerCutaway.active);
  }
  const bootstrapSetupMs = performance.now() - buildStartedAt;
  logMovementEvent(
    `WORLD REFRESH ${previousSliceY === null ? "surface" : `slice:${previousSliceY}`} → ${cutawayStateKey} y=${initialPosition.y.toFixed(3)} surface=${surfaceReferenceY.toFixed(3)} stateGap=${statePoseGap?.toFixed(3) ?? "missing"} chunks=${payload.chunks.length} setup=${bootstrapSetupMs.toFixed(1)}ms queued=${queuedChunkRebuilds.size}`,
  );
  worldReady = true;
  if (fastWorldRequested) window.setTimeout(() => {
    requestRapidTownAssets();
    requestRapidTownNpcAssets();
    requestGreenwoodAssets();
  }, 250);
  lastWorldBootstrapAt = performance.now();
  snapFrameHistory.length = 0;
  status.textContent = fastWorldRequested
    ? "Fast World ready · choose a Calling, explore freely and test your build against regional enemies."
    : isInGreenwoodRegion(initialPosition.x, initialPosition.z)
    ? "Greenwood Outskirts · harvest oak timber and investigate the abandoned forester camp."
    : "Welcome to the Town of Beginnings. Starter supplies are nearby; follow the south road when ready.";
}

const keys = new Set<string>();
let lastKeyboardEvent = "none";
let lastMovementDialogUnlockAt = Number.NEGATIVE_INFINITY;
let lastMovementWorldRefreshAt = Number.NEGATIVE_INFINITY;
function visibleEditableTarget(target: EventTarget | null): { editable: boolean; visible: boolean } {
  const element = target instanceof HTMLElement ? target : null;
  const editable = element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement
    || element instanceof HTMLSelectElement || Boolean(element?.isContentEditable);
  const visible = Boolean(element && !element.closest("[hidden], [inert]") && element.getClientRects().length > 0);
  return { editable, visible };
}
// Capture movement before a stale focused control can swallow it. This particularly matters
// after onboarding/dialog transitions, where a closed input may remain document.activeElement.
window.addEventListener("keydown", event => {
  const target = visibleEditableTarget(event.target);
  const movementCode = normalizedMovementCode(event.code, event.key);
  lastKeyboardEvent = `${event.key || "∅"}/${event.code || "∅"} target=${event.target instanceof HTMLElement ? event.target.tagName : "unknown"}`;
  if (!movementCode || !shouldCaptureMovementKey(event.code, event.key, target.editable, target.visible)) return;
  repairStaleActivePopup();
  keys.add(movementCode);
  if (!worldReady && room && performance.now() - lastMovementWorldRefreshAt >= 1_000) {
    lastMovementWorldRefreshAt = performance.now();
    room.send("world:ready");
    logMovementEvent("MOVEMENT REQUESTED WORLD REFRESH");
  }
  // Reassert the real UI state whenever the player expresses movement intent. A dropped
  // dialog-close message previously left the server discarding every move indefinitely.
  if (!protectedDialogPresented() && (!event.repeat || performance.now() - lastMovementDialogUnlockAt >= 1_000)) {
    lastMovementDialogUnlockAt = performance.now();
    syncProtectedDialog(true);
  }
  if (target.editable && !target.visible) canvas.focus({ preventScroll: true });
}, true);
window.addEventListener("keyup", event => {
  const movementCode = normalizedMovementCode(event.code, event.key);
  if (movementCode) keys.delete(movementCode);
}, true);
let awaitingReturnState = false;
let townReturnPosition: { x: number; y: number; z: number } | null = null;
const defeatScreen = document.querySelector<HTMLElement>("#defeat-screen")!;
const defeatTitle = document.querySelector<HTMLElement>("#defeat-title")!;
