    if (detail) detail.textContent = `DMG +${reward.damage} · HASTE ${reward.haste} · HP +${reward.vitality * 5} · RELICS ${reward.relics}`;
    status.textContent = `${reward.rare ? "RARE " : ""}${reward.name} claimed · next wave incoming.`;
